*,
*::before,
*::after {
  box-sizing: border-box;
}

:root {
  --bg: #f4f5f7;
  --card: #ffffff;
  --text: #1f2933;
  --muted: #6b7280;
  --border: #d9dde3;
  --accent: #2563eb;
  --accent-dark: #1d4ed8;
  --error: #b91c1c;
  --radius: 10px;
}

body {
  margin: 0;
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
}

.container {
  max-width: 720px;
  margin: 0 auto;
  padding: 24px 16px 48px;
}

.header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  margin-bottom: 20px;
}

h1 {
  margin: 0;
  font-size: 1.75rem;
}

h2 {
  margin: 0 0 16px;
  font-size: 1.15rem;
}

.total {
  background: var(--accent);
  color: #fff;
  border-radius: var(--radius);
  padding: 10px 18px;
  text-align: right;
}

.total-label {
  display: block;
  font-size: 0.8rem;
  opacity: 0.85;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.total-value {
  font-size: 1.5rem;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}

.card {
  background: var(--card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px;
  margin-bottom: 20px;
}

/* Form */
#expense-form {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 4px 16px;
}

.field {
  display: flex;
  flex-direction: column;
}

.field-wide {
  grid-column: 1 / -1;
}

label {
  font-size: 0.9rem;
  font-weight: 600;
  margin-bottom: 4px;
}

.optional {
  font-weight: 400;
  color: var(--muted);
}

input,
select {
  font: inherit;
  padding: 8px 10px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: #fff;
  color: inherit;
  width: 100%;
}

input:focus,
select:focus {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
  border-color: var(--accent);
}

input[aria-invalid="true"],
select[aria-invalid="true"] {
  border-color: var(--error);
}

.error {
  color: var(--error);
  font-size: 0.8rem;
  min-height: 1.2em;
  margin: 2px 0 6px;
}

.btn {
  grid-column: 1 / -1;
  justify-self: start;
  font: inherit;
  font-weight: 600;
  padding: 10px 20px;
  border: none;
  border-radius: 6px;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
}

.btn:hover {
  background: var(--accent-dark);
}

/* List */
.count {
  color: var(--muted);
  font-weight: 400;
  font-size: 0.95rem;
}

.empty {
  color: var(--muted);
  margin: 0;
}

.empty[hidden] {
  display: none;
}

.expense-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.expense {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 2px 12px;
  padding: 12px 0;
  border-top: 1px solid var(--border);
}

.expense:first-child {
  border-top: none;
  padding-top: 0;
}

.expense-main {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.expense-amount {
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  text-align: right;
}

.expense-meta {
  grid-column: 1 / -1;
  color: var(--muted);
  font-size: 0.85rem;
}

.badge {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 999px;
  background: #e5e7eb;
  color: #374151;
}

.badge-food { background: #fef3c7; color: #92400e; }
.badge-transport { background: #dbeafe; color: #1e40af; }
.badge-bills { background: #fee2e2; color: #991b1b; }
.badge-fun { background: #ede9fe; color: #5b21b6; }
.badge-other { background: #e5e7eb; color: #374151; }

.expense-note {
  word-break: break-word;
}

@media (max-width: 560px) {
  #expense-form {
    grid-template-columns: 1fr;
  }
}

