mkdir -p /tmp/exp-check && cat > /tmp/exp-check/check.js <<'EOF'
const L = require(process.argv[2]);
const assert = require('assert');
assert.strictEqual(L.calculateTotal([{amount:0.1},{amount:0.2}]), 0.3);
assert.strictEqual(L.calculateTotal([]), 0);
const a = L.createExpense({amount:'12.5',category:'Food',date:'2026-11-20',note:' lunch '}, 'a', 1);
const b = L.createExpense({amount:3,category:'Fun',date:'2026-11-22'}, 'b', 2);
const c = L.createExpense({amount:7,category:'Bills',date:'2026-11-20'}, 'c', 3);
assert.deepStrictEqual(a, {id:'a',amount:12.5,category:'Food',date:'2026-11-20',note:'lunch',createdAt:1});
const list = [a,b,c];
assert.deepStrictEqual(L.sortNewestFirst(list).map(e=>e.id), ['b','c','a']);
assert.deepStrictEqual(list.map(e=>e.id), ['a','b','c'], 'no mutation');
assert.strictEqual(L.calculateTotal(list), 22.5);
assert.deepStrictEqual(Object.keys(L.validateExpense({amount:'',category:'X',date:'2026-02-30'})).sort(), ['amount','category','date']);
