  margin: 0;
  font-size: 1.75rem;
}

h2 {
  margin: 0 0 16px;
  font-size: 1.15rem;
}

.total {
  background: var(--accent);
  color: #fff;
  border-radius: var(--radius);
  padding: 10px 18px;
  text-align: right;
}

