}

.icon-btn {
  font: inherit;
  font-size: 1.25rem;
  line-height: 1;
  width: 36px;
  height: 36px;
  border: 1px solid var(--border);
  border-radius: 6px;
  background: #fff;
  color: var(--text);
  cursor: pointer;
}

.icon-btn:hover {
  background: var(--bg);
}

.icon-btn:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

.summary-total {
  margin: 0 0 16px;
  color: var(--muted);
