/*
 * Browser glue: DOM, events and localStorage.
 * All calculations live in logic.js (window.ExpenseLogic).
 */
(function () {
  "use strict";

  var L = window.ExpenseLogic;
  var STORAGE_KEY = "expense-tracker.expenses";

  var form = document.getElementById("expense-form");
  var amountInput = document.getElementById("amount");
  var categoryInput = document.getElementById("category");
  var dateInput = document.getElementById("date");
  var noteInput = document.getElementById("note");
  var listEl = document.getElementById("expense-list");
  var totalEl = document.getElementById("total");
  var countEl = document.getElementById("count");
  var emptyEl = document.getElementById("empty");

  var fields = {
    amount: amountInput,
    category: categoryInput,
    date: dateInput,
    note: noteInput
  };

  // ---- Storage ------------------------------------------------------------

  function loadExpenses() {
    try {
      return L.parseStoredExpenses(localStorage.getItem(STORAGE_KEY) || "[]");
    } catch (e) {
      // localStorage can be unavailable (e.g. blocked by browser settings).
      return [];
    }
  }

  function saveExpenses(list) {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(list));
      return true;
    } catch (e) {
      return false;
    }
  }

  function makeId() {
    return Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 8);
  }

  // ---- Rendering ----------------------------------------------------------

  function formatDisplayDate(iso) {
    var p = iso.split("-").map(Number);
    return new Date(p[0], p[1] - 1, p[2]).toLocaleDateString(undefined, {
      year: "numeric",
      month: "short",
      day: "numeric"
    });
  }

  function renderExpense(expense) {
    var li = document.createElement("li");
    li.className = "expense";

    var main = document.createElement("div");
    main.className = "expense-main";

    var badge = document.createElement("span");
    badge.className = "badge badge-" + expense.category.toLowerCase();
    badge.textContent = expense.category;
    main.appendChild(badge);

    if (expense.note) {
      var note = document.createElement("span");
      note.className = "expense-note";
      note.textContent = expense.note; // textContent: never inject HTML
      main.appendChild(note);
    }

    var amount = document.createElement("span");
    amount.className = "expense-amount";
    amount.textContent = L.formatAmount(expense.amount);

    var meta = document.createElement("time");
    meta.className = "expense-meta";
    meta.dateTime = expense.date;
    meta.textContent = formatDisplayDate(expense.date);

    li.appendChild(main);
    li.appendChild(amount);
    li.appendChild(meta);
    return li;
  }

  function render() {
    var sorted = L.sortNewestFirst(expenses);

    listEl.replaceChildren.apply(listEl, sorted.map(renderExpense));
    totalEl.textContent = L.formatAmount(L.calculateTotal(expenses));
    countEl.textContent = sorted.length ? "(" + sorted.length + ")" : "";
    emptyEl.hidden = sorted.length > 0;
  }

  // ---- Form ---------------------------------------------------------------

  function showErrors(errors) {
    Object.keys(fields).forEach(function (name) {
      var msg = errors[name] || "";
      document.getElementById(name + "-error").textContent = msg;
      if (msg) {
        fields[name].setAttribute("aria-invalid", "true");
      } else {
        fields[name].removeAttribute("aria-invalid");
      }
    });
  }

  function readForm() {
    return {
      amount: amountInput.value,
      category: categoryInput.value,
      date: dateInput.value,
      note: noteInput.value
    };
  }

  function resetForm() {
    amountInput.value = "";
    noteInput.value = "";
    // Keep the chosen category and date: handy when entering several at once.
    amountInput.focus();
  }

  function onSubmit(event) {
    event.preventDefault();
    var input = readForm();
    var errors = L.validateExpense(input);
    showErrors(errors);

    var firstBad = Object.keys(fields).find(function (n) { return errors[n]; });
    if (firstBad) {
      fields[firstBad].focus();
      return;
    }

    var expense = L.createExpense(input, makeId(), Date.now());
    expenses = L.addExpense(expenses, expense);
    if (!saveExpenses(expenses)) {
      document.getElementById("note-error").textContent =
        "Added, but could not save to this browser's storage.";
    }
    render();
    resetForm();
  }

  // ---- Init ---------------------------------------------------------------

  L.CATEGORIES.forEach(function (cat) {
    var opt = document.createElement("option");
    opt.value = cat;
    opt.textContent = cat;
    categoryInput.appendChild(opt);
  });

  dateInput.value = L.toISODate(new Date());

  var expenses = loadExpenses();

  form.addEventListener("submit", onSubmit);

  // Clear a field's error as soon as the user edits it.
  Object.keys(fields).forEach(function (name) {
    fields[name].addEventListener("input", function () {
      document.getElementById(name + "-error").textContent = "";
      fields[name].removeAttribute("aria-invalid");
    });
  });

  // Stay in sync if the tracker is open in another tab.
  window.addEventListener("storage", function (e) {
    if (e.key === STORAGE_KEY) {
      expenses = loadExpenses();
      render();
    }
  });

  render();
})();

