const L = require('./logic.js');
const assert = require('assert');

// --- Step 1 logic still works
const a = L.createExpense({amount:'12.5',category:'Food',date:'2026-11-20'}, 'a', 1);
const b = L.createExpense({amount:'0.1',category:'Food',date:'2026-11-02'}, 'b', 2);
const c = L.createExpense({amount:'0.2',category:'Bills',date:'2026-11-30'}, 'c', 3);
const d = L.createExpense({amount:'99',category:'Fun',date:'2026-10-31'}, 'd', 4);
const e = L.createExpense({amount:'5',category:'Transport',date:'2025-11-15'}, 'e', 5);
const all = [a,b,c,d,e];
assert.deepStrictEqual(L.sortNewestFirst(all).map(x=>x.id), ['c','a','b','d','e']);
assert.strictEqual(L.calculateTotal(all), 116.8);

// --- Month helpers
assert.ok(L.isValidMonth('2026-11')); assert.ok(!L.isValidMonth('2026-13'));
assert.ok(!L.isValidMonth('2026-1')); assert.ok(!L.isValidMonth('')); assert.ok(!L.isValidMonth(null));
assert.strictEqual(L.monthOf('2026-11-22'), '2026-11');
assert.strictEqual(L.shiftMonth('2026-01', -1), '2025-12');
assert.strictEqual(L.shiftMonth('2026-12', 1), '2027-01');
assert.strictEqual(L.shiftMonth('2026-05', -17), '2024-12');
assert.strictEqual(L.shiftMonth('2026-05', 0), '2026-05');
assert.deepStrictEqual(L.filterByMonth(all, '2026-11').map(x=>x.id), ['a','b','c']);
assert.deepStrictEqual(L.filterByMonth(all, '2025-11').map(x=>x.id), ['e'], 'same month, other year excluded');

// --- summarizeMonth
const s = L.summarizeMonth(all, '2026-11');
assert.strictEqual(s.month, '2026-11'); assert.strictEqual(s.count, 3); assert.strictEqual(s.total, 12.8);
assert.deepStrictEqual(s.categories.map(r=>r.category), L.CATEGORIES, 'fixed order, all present');
const food = s.categories[0];
assert.strictEqual(food.total, 12.6); assert.strictEqual(food.count, 2); assert.strictEqual(food.ofMax, 1);
assert.strictEqual(Math.round(food.share*1000), 984);
const bills = s.categories[2];
assert.strictEqual(bills.total, 0.2); assert.strictEqual(bills.count, 1);
assert.strictEqual(s.categories[1].total, 0); assert.strictEqual(s.categories[1].share, 0); assert.strictEqual(s.categories[1].ofMax, 0);
const empty = L.summarizeMonth(all, '2020-01');
assert.strictEqual(empty.count, 0); assert.strictEqual(empty.total, 0);
assert.ok(empty.categories.every(r => r.total === 0 && r.share === 0 && r.ofMax === 0), 'no divide-by-zero');
assert.strictEqual(L.summarizeMonth([], '2026-11').count, 0);
assert.strictEqual(all.length, 5, 'no mutation');
console.log('logic checks passed');

// --- app.js smoke test against a tiny fake DOM
const vm = require('vm'); const fs = require('fs');
function el(tag, id) {
  const e = { tagName: tag, id, value: '', textContent: '', hidden: false, children: [], attrs: {}, listeners: {},
    className: '', dateTime: '', tabIndex: -1, style: {}, parent: null,
    offsetLeft: 100, offsetTop: 40, offsetWidth: 50, clientWidth: 600,
    get classList() { const self = this; return {
      add(c) { if (!self.className.split(' ').includes(c)) self.className = (self.className + ' ' + c).trim(); },
      remove(c) { self.className = self.className.split(' ').filter(x => x !== c).join(' '); },
      contains(c) { return self.className.split(' ').includes(c); } }; },
    appendChild(c) { c.parent = this; this.children.push(c); return c; },
    replaceChildren(...k) { k.forEach(c => c.parent = this); this.children = k; },
    setAttribute(k, v) { this.attrs[k] = String(v); }, removeAttribute(k) { delete this.attrs[k]; },
    addEventListener(t, f) { this.listeners[t] = f; }, focus() {},
    querySelector(sel) { const cls = sel.slice(1); const walk = n => { for (const c of n.children) { if (c.className.split(' ').includes(cls)) return c; const r = walk(c); if (r) return r; } return null; }; return walk(this); },
    closest(sel) { const cls = sel.slice(1); let n = this; while (n) { if ((n.className||'').split(' ').includes(cls)) return n; n = n.parent; } return null; } };
  return e;
}
const els = {}; const getEl = id => els[id] || (els[id] = el('div', id));
const store = {};
const ctx = { console, Date, Math, JSON, Object, String, Number, Array,
  document: { getElementById: getEl, createElement: t => el(t) },
  localStorage: { getItem: k => store[k] ?? null, setItem: (k, v) => { store[k] = String(v); } },
  window: { addEventListener() {}, ExpenseLogic: L } };
vm.createContext(ctx);
const run = () => vm.runInContext(fs.readFileSync('./app.js', 'utf8'), ctx);
run();

const thisMonth = L.monthOf(L.toISODate(new Date()));
assert.strictEqual(getEl('month').value, thisMonth, 'defaults to current month');
assert.strictEqual(getEl('summary-empty').hidden, false);
assert.strictEqual(getEl('chart').hidden, true);
assert.strictEqual(getEl('table-view').hidden, true);

const submit = () => getEl('expense-form').listeners.submit({ preventDefault() {} });
const add = (amount, category, date) => { Object.assign(getEl('amount'), {value: amount}); getEl('category').value = category; getEl('date').value = date; submit(); };
add('40', 'Food', thisMonth + '-01');
add('10', 'Fun', thisMonth + '-02');
add('7.5', 'Bills', L.shiftMonth(thisMonth, -1) + '-15');

assert.strictEqual(getEl('month-total').textContent, '50.00');
assert.ok(getEl('month-count').textContent.includes('2 expenses'));
assert.strictEqual(getEl('chart').hidden, false);
const rows = getEl('bar-chart').children;
assert.strictEqual(rows.length, 5);
assert.deepStrictEqual(rows.map(r => r.children[0].textContent), L.CATEGORIES);
assert.strictEqual(rows[0].children[1].children[0].style.width, 'max(4px, 100.00%)', 'Food is the max');
assert.strictEqual(rows[3].children[1].children[0].style.width, 'max(4px, 25.00%)', 'Fun is 1/4 of Food');
assert.strictEqual(rows[1].children[1].children.length, 0, 'zero category draws no bar');
assert.ok(rows[1].className.includes('is-zero'));
assert.strictEqual(rows[0].children[2].textContent, '40.00');
assert.strictEqual(rows[0].tabIndex, 0);
assert.ok(rows[0].attrs['aria-label'].startsWith('Food: 40.00, 80% of the month, 2'.slice(0, 30)));
const table = getEl('summary-table').children;
assert.strictEqual(table.length, 6);
assert.deepStrictEqual(table[0].children.map(c => c.textContent), ['Food','1','40.00','80%']);
assert.deepStrictEqual(table[5].children.map(c => c.textContent), ['Total','2','50.00','100%']);

// Tooltip on hover / focus
getEl('bar-chart').listeners.mouseover({ target: rows[3].children[2] });
assert.strictEqual(getEl('chart-tooltip').hidden, false);
assert.strictEqual(getEl('chart-tooltip').children[0].textContent, 'Fun · 10.00');
assert.ok(rows[3].className.includes('is-active'));
getEl('bar-chart').listeners.mouseleave({});
assert.strictEqual(getEl('chart-tooltip').hidden, true);
assert.ok(!rows[3].className.includes('is-active'));
getEl('bar-chart').listeners.focusin({ target: rows[0] });
assert.strictEqual(getEl('chart-tooltip').hidden, false);
getEl('bar-chart').listeners.keydown({ key: 'Escape' });
assert.strictEqual(getEl('chart-tooltip').hidden, true);

// Prev / next and typed month
getEl('prev-month').listeners.click();
