/*
 * Pure CSV reading and writing: no DOM, no files, no localStorage.
 *
 * Low level:  parseCSV(text) -> rows,  stringifyCSV(rows) -> text   (RFC 4180)
 * Expenses:   expensesToCSV(expenses) -> text
 *             csvToExpenses(text) -> { expenses, errors, rowCount }
 *
 * Loads in the browser (window.ExpenseCSV, after logic.js) or from Node.
 */
(function (root, factory) {
  "use strict";
  if (typeof module !== "undefined" && module.exports) {
    module.exports = factory(require("./logic.js"));
  } else {
    root.ExpenseCSV = factory(root.ExpenseLogic);
  }
})(typeof globalThis !== "undefined" ? globalThis : this, function (L) {
  "use strict";

  var HEADER = ["date", "category", "amount", "note"];
  var REQUIRED = ["date", "category", "amount"];

  // ---- Low-level CSV ------------------------------------------------------

  /**
   * Parse CSV text into records: [{ fields: [...], line: n }], where `line`
   * is the 1-based line the record starts on (records can span lines when a
   * quoted field contains a newline).
   *
   * Handles: quoted fields, commas and newlines inside quotes, "" as an
   * escaped quote, LF / CRLF / CR line endings, a UTF-8 BOM, and a missing
   * or present trailing newline. A stray quote inside an unquoted field is
   * kept as a literal character. An unclosed quote throws.
   */
  function parseCSVRecords(text) {
    if (typeof text !== "string") throw new TypeError("CSV input must be a string");
    if (text.charCodeAt(0) === 0xfeff) text = text.slice(1);

    var records = [];
    var fields = [];
    var field = "";
    var inQuotes = false;
    var wasQuoted = false;   // current field started with a quote
    var line = 1;
    var recordLine = 1;
    var quoteLine = 1;
    var i = 0;
    var n = text.length;

    function endField() {
      fields.push(field);
      field = "";
      wasQuoted = false;
    }

    function endRecord() {
      endField();
      records.push({ fields: fields, line: recordLine });
      fields = [];
    }

    while (i < n) {
      var ch = text[i];

      if (inQuotes) {
        if (ch === '"') {
          if (text[i + 1] === '"') {
            field += '"';
            i += 2;
            continue;
          }
          inQuotes = false;
          i += 1;
          continue;
        }
        if (ch === "\r" || ch === "\n") {
          // Keep the newline as written, but normalise CRLF to one step.
          if (ch === "\r" && text[i + 1] === "\n") {
            field += "\r\n";
            i += 2;
          } else {
            field += ch;
            i += 1;
          }
          line += 1;
          continue;
        }
        field += ch;
        i += 1;
        continue;
      }

      if (ch === ",") {
        endField();
        i += 1;
      } else if (ch === "\r" || ch === "\n") {
        endRecord();
        i += ch === "\r" && text[i + 1] === "\n" ? 2 : 1;
        line += 1;
        recordLine = line;
      } else if (ch === '"' && field === "" && !wasQuoted) {
        inQuotes = true;
        wasQuoted = true;
        quoteLine = line;
        i += 1;
      } else {
        field += ch;
        i += 1;
      }
    }

    if (inQuotes) {
      var err = new Error("Line " + quoteLine + ": a quoted value is never closed.");
      err.line = quoteLine;
      throw err;
    }

    // Text that doesn't end in a newline still has a final record to flush.
    if (field !== "" || fields.length > 0 || wasQuoted) {
      endRecord();
    }

    return records;
  }

  /** Parse CSV text into an array of rows (arrays of strings). */
  function parseCSV(text) {
    return parseCSVRecords(text).map(function (r) { return r.fields; });
  }

  function needsQuotes(s) {
    return /[",\r\n]/.test(s) || /^\s|\s$/.test(s);
  }

  /** Turn one value into a CSV field, quoting only when needed. */
  function formatField(value) {
    var s = value == null ? "" : String(value);
    return needsQuotes(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
  }

  /** Write rows (arrays of values) as CSV text with CRLF line endings. */
  function stringifyCSV(rows) {
    return (rows || []).map(function (row) {
      return row.map(formatField).join(",");
    }).join("\r\n") + ((rows || []).length ? "\r\n" : "");
  }

  // ---- Spreadsheet safety ------------------------------------------------
  // A cell starting with = + - @ can run as a formula when the CSV is opened
  // in Excel / Sheets. On export, such text gets a leading apostrophe; on
  // import, that apostrophe is removed again so a round trip is lossless.

  var FORMULA_START = /^[=+\-@\t\r]/;

  function protectFormula(s) {
    return FORMULA_START.test(s) ? "'" + s : s;
  }

  function unprotectFormula(s) {
    return s.charAt(0) === "'" && FORMULA_START.test(s.slice(1)) ? s.slice(1) : s;
  }

  // ---- Expenses -> CSV ----------------------------------------------------

  /** Export expenses (newest first) as CSV text with a header row. */
  function expensesToCSV(expenses) {
    var rows = [HEADER.slice()];
    L.sortNewestFirst(expenses || []).forEach(function (e) {
      rows.push([
        e.date,
        e.category,
        (L.toCents(e.amount) / 100).toFixed(2),
        protectFormula(e.note || "")
      ]);
    });
    return stringifyCSV(rows);
  }

  // ---- CSV -> expenses ----------------------------------------------------

