/*
 * Browser glue: DOM, events and localStorage.
 * All calculations live in logic.js (window.ExpenseLogic).
 */
(function () {
  "use strict";

  var L = window.ExpenseLogic;
  var STORAGE_KEY = "expense-tracker.expenses";

  var form = document.getElementById("expense-form");
  var amountInput = document.getElementById("amount");
  var categoryInput = document.getElementById("category");
  var dateInput = document.getElementById("date");
  var noteInput = document.getElementById("note");
  var listEl = document.getElementById("expense-list");
  var totalEl = document.getElementById("total");
  var countEl = document.getElementById("count");
  var emptyEl = document.getElementById("empty");

  var monthInput = document.getElementById("month");
  var prevMonthBtn = document.getElementById("prev-month");
  var nextMonthBtn = document.getElementById("next-month");
  var monthLabelEl = document.getElementById("month-label");
  var monthTotalEl = document.getElementById("month-total");
  var monthCountEl = document.getElementById("month-count");
  var summaryEmptyEl = document.getElementById("summary-empty");
  var chartEl = document.getElementById("chart");
  var barChartEl = document.getElementById("bar-chart");
  var tooltipEl = document.getElementById("chart-tooltip");
  var tableViewEl = document.getElementById("table-view");
  var summaryTableEl = document.getElementById("summary-table");

  var selectedMonth = L.monthOf(L.toISODate(new Date()));

  var fields = {
    amount: amountInput,
    category: categoryInput,
    date: dateInput,
    note: noteInput
  };

  // ---- Storage ------------------------------------------------------------

  function loadExpenses() {
    try {
      return L.parseStoredExpenses(localStorage.getItem(STORAGE_KEY) || "[]");
    } catch (e) {
      // localStorage can be unavailable (e.g. blocked by browser settings).
      return [];
    }
  }

  function saveExpenses(list) {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(list));
      return true;
    } catch (e) {
      return false;
    }
  }

  function makeId() {
    return Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 8);
  }

  // ---- Rendering ----------------------------------------------------------

  function formatDisplayDate(iso) {
    var p = iso.split("-").map(Number);
    return new Date(p[0], p[1] - 1, p[2]).toLocaleDateString(undefined, {
      year: "numeric",
      month: "short",
      day: "numeric"
    });

