"use strict";

const { describe, test } = require("node:test");
const assert = require("node:assert/strict");
const L = require("../logic.js");
const C = require("../csv.js");

const HEADER = "date,category,amount,note\n";

describe("parseCSV", () => {
  test("empty input gives no rows", () => {
    assert.deepEqual(C.parseCSV(""), []);
    assert.deepEqual(C.parseCSV("﻿"), []);
  });

  test("simple rows, with and without a trailing newline", () => {
    assert.deepEqual(C.parseCSV("a,b,c\n1,2,3"), [["a", "b", "c"], ["1", "2", "3"]]);
    assert.deepEqual(C.parseCSV("a,b,c\n1,2,3\n"), [["a", "b", "c"], ["1", "2", "3"]]);
  });

  test("CRLF, LF and lone CR line endings", () => {
    const expected = [["a", "b"], ["1", "2"], ["3", "4"]];
    assert.deepEqual(C.parseCSV("a,b\r\n1,2\r\n3,4\r\n"), expected);
    assert.deepEqual(C.parseCSV("a,b\r1,2\r3,4"), expected);
    assert.deepEqual(C.parseCSV("a,b\n1,2\r\n3,4"), expected);
  });

  test("quoted commas stay in one field", () => {
    assert.deepEqual(C.parseCSV('x,"Lunch, with Sam",y'), [["x", "Lunch, with Sam", "y"]]);
  });

  test("escaped quotes inside quoted fields", () => {
    assert.deepEqual(C.parseCSV('"She said ""hi""",b'), [['She said "hi"', "b"]]);
    assert.deepEqual(C.parseCSV('""""'), [['"']]);
  });

  test("newlines inside quoted fields", () => {
    assert.deepEqual(C.parseCSV('a,"line 1\nline 2",c\nd,e,f'), [["a", "line 1\nline 2", "c"], ["d", "e", "f"]]);
    assert.deepEqual(C.parseCSV('"x\r\ny"'), [["x\r\ny"]]);
  });

  test("empty fields, including a quoted empty field at the end", () => {
    assert.deepEqual(C.parseCSV("a,,c\n,,"), [["a", "", "c"], ["", "", ""]]);
    assert.deepEqual(C.parseCSV('a,""'), [["a", ""]]);
    assert.deepEqual(C.parseCSV('""'), [[""]]);
  });

  test("blank lines come through as a single empty field", () => {
    assert.deepEqual(C.parseCSV("a\n\nb"), [["a"], [""], ["b"]]);
  });

  test("strips a UTF-8 BOM", () => {
    assert.deepEqual(C.parseCSV("﻿date,amount"), [["date", "amount"]]);
  });

  test("keeps unicode as-is", () => {
    assert.deepEqual(C.parseCSV("café,🍕,日本"), [["café", "🍕", "日本"]]);
  });

  test("a stray quote in an unquoted field is kept literally", () => {
    assert.deepEqual(C.parseCSV('5" screen,b'), [['5" screen', "b"]]);
  });

  test("an unclosed quote throws, naming the line it started on", () => {
    assert.throws(() => C.parseCSV('a,b\n1,"oops\n2,3'), (err) => err.line === 2 && /never closed/.test(err.message));
  });

  test("rejects non-string input", () => {
    assert.throws(() => C.parseCSV(null), TypeError);
  });

  test("parseCSVRecords reports the starting line of each record", () => {
    const recs = C.parseCSVRecords('h\n"multi\nline"\n\nlast');
    assert.deepEqual(recs.map((r) => r.line), [1, 2, 4, 5]);
  });
});

describe("stringifyCSV", () => {
  test("empty input gives empty text", () => {
    assert.equal(C.stringifyCSV([]), "");
  });

  test("plain fields are not quoted; rows end with CRLF", () => {
    assert.equal(C.stringifyCSV([["a", "b"], [1, 2]]), "a,b\r\n1,2\r\n");
  });

  test("quotes fields with commas, quotes, newlines or edge spaces", () => {
    assert.equal(C.formatField("a,b"), '"a,b"');
    assert.equal(C.formatField('say "hi"'), '"say ""hi"""');
    assert.equal(C.formatField("two\nlines"), '"two\nlines"');
    assert.equal(C.formatField(" padded "), '" padded "');
    assert.equal(C.formatField(null), "");
    assert.equal(C.formatField(undefined), "");
  });

  test("round-trips through parseCSV", () => {
    const rows = [["a,b", 'q"q', "line\r\nbreak", "", " sp "], ["plain", "é", "🍕", "x", "y"]];
    assert.deepEqual(C.parseCSV(C.stringifyCSV(rows)), rows);
  });
});

describe("parseAmount", () => {
  test("accepts ordinary amounts", () => {
    assert.deepEqual(C.parseAmount("12"), { value: 12 });
    assert.deepEqual(C.parseAmount("12.5"), { value: 12.5 });
    assert.deepEqual(C.parseAmount(" 12.50 "), { value: 12.5 });
    assert.deepEqual(C.parseAmount(".5"), { value: 0.5 });
    assert.deepEqual(C.parseAmount("1,234.56"), { value: 1234.56 });
    assert.deepEqual(C.parseAmount("1,234,567"), { value: 1234567 });
  });

  test("rejects bad amounts with a reason", () => {
    const cases = {
      "": /missing/,
      "   ": /missing/,
      abc: /not a number/,
      "12abc": /not a number/,
      "$12": /not a number/,
      "1.2.3": /not a number/,
      "12,34": /not a number/,
      "1e3": /not a number/,
      "0": /greater than 0/,
      "0.00": /greater than 0/,
      "-5": /greater than 0/,
      "-0.5": /greater than 0/,
      "12.345": /2 decimal places/
    };
    for (const [input, reason] of Object.entries(cases)) {
      const r = C.parseAmount(input);
      assert.equal(r.value, undefined, `"${input}" should be rejected`);
      assert.match(r.error, reason, `"${input}"`);
    }
  });
});

describe("expensesToCSV", () => {
  const list = [
    L.createExpense({ amount: 3, category: "Food", date: "2026-11-01", note: "Coffee, large" }, "a", 1),
    L.createExpense({ amount: 1234.5, category: "Bills", date: "2026-11-20", note: 'The "big" one' }, "b", 2),
    L.createExpense({ amount: 0.1, category: "Fun", date: "2026-10-05" }, "c", 3)
  ];

  test("no expenses gives just the header", () => {
    assert.equal(C.expensesToCSV([]), "date,category,amount,note\r\n");
  });

  test("writes a header and rows newest first, amounts without separators", () => {
    assert.equal(C.expensesToCSV(list),
      "date,category,amount,note\r\n" +
      '2026-11-20,Bills,1234.50,"The ""big"" one"\r\n' +
      '2026-11-01,Food,3.00,"Coffee, large"\r\n' +
      "2026-10-05,Fun,0.10,\r\n");
  });

  test("neutralises notes that a spreadsheet would run as formulas", () => {
    const risky = ["=HYPERLINK(\"x\")", "+1", "-1", "@SUM(A1)"].map((note, i) =>
      L.createExpense({ amount: 1, category: "Other", date: "2026-01-0" + (i + 1), note }, String(i), i));
    const rows = C.parseCSV(C.expensesToCSV(risky)).slice(1);
    for (const row of rows) {
      assert.equal(row[3][0], "'", `note ${row[3]} should be prefixed`);
    }
  });

  test("round-trips through csvToExpenses without loss", () => {
    const tricky = list.concat([
      L.createExpense({ amount: 2, category: "Other", date: "2026-09-09", note: "=1+1" }, "d", 4),
      L.createExpense({ amount: 2, category: "Other", date: "2026-09-08", note: "'=already quoted" }, "e", 5),
      L.createExpense({ amount: 2, category: "Transport", date: "2026-09-07", note: "multi\nline 🚌" }, "f", 6)
    ]);
    const back = C.csvToExpenses(C.expensesToCSV(tricky));
    assert.deepEqual(back.errors, []);
    const strip = (e) => ({ date: e.date, category: e.category, amount: e.amount, note: e.note });
    assert.deepEqual(back.expenses, L.sortNewestFirst(tricky).map(strip));
  });
});

describe("csvToExpenses", () => {
  test("empty file", () => {
    for (const text of ["", "﻿", "\n\n", "  ,  \r\n"]) {
      const r = C.csvToExpenses(text);
      assert.deepEqual(r.expenses, []);
      assert.equal(r.rowCount, 0);
      assert.deepEqual(r.errors, [{ line: null, message: "The file is empty." }]);
    }
  });

  test("header only: no expenses and no errors", () => {
    assert.deepEqual(C.csvToExpenses(HEADER), { expenses: [], errors: [], rowCount: 0 });
  });

  test("reads valid rows", () => {
    const r = C.csvToExpenses(HEADER + "2026-11-22,Food,12.50,Lunch\n2026-11-21,Transport,3,\n");
    assert.deepEqual(r.errors, []);
    assert.equal(r.rowCount, 2);
    assert.deepEqual(r.expenses, [
      { date: "2026-11-22", category: "Food", amount: 12.5, note: "Lunch" },
      { date: "2026-11-21", category: "Transport", amount: 3, note: "" }
    ]);
  });

  test("quoted commas in notes and amounts", () => {
    const r = C.csvToExpenses(HEADER + '2026-11-22,Bills,"1,250.00","Rent, gas, water"\n');
    assert.deepEqual(r.errors, []);
    assert.deepEqual(r.expenses, [{ date: "2026-11-22", category: "Bills", amount: 1250, note: "Rent, gas, water" }]);
  });

  test("an unquoted comma in a note shifts nothing it shouldn't (extra columns ignored)", () => {
    const r = C.csvToExpenses(HEADER + "2026-11-22,Food,5,Lunch, with Sam\n");
    assert.deepEqual(r.errors, []);
    assert.equal(r.expenses[0].note, "Lunch");
  });

  test("bad amounts are reported per line and skipped; good rows still import", () => {
    const text = HEADER +
      "2026-11-01,Food,abc,bad\n" +
      "2026-11-02,Food,12.50,good\n" +
      "2026-11-03,Food,-4,negative\n" +
      "2026-11-04,Food,,missing\n" +
      "2026-11-05,Food,0,zero\n" +
      "2026-11-06,Food,1.999,too precise\n";
    const r = C.csvToExpenses(text);
    assert.equal(r.rowCount, 6);
    assert.deepEqual(r.expenses.map((e) => e.note), ["good"]);
    assert.deepEqual(r.errors.map((e) => e.line), [2, 4, 5, 6, 7]);
    assert.match(r.errors[0].message, /"abc" is not a number/);
    assert.match(r.errors[1].message, /greater than 0/);
    assert.match(r.errors[2].message, /missing/);
    assert.match(r.errors[3].message, /greater than 0/);
    assert.match(r.errors[4].message, /2 decimal places/);
  });

  test("bad dates and categories are reported, all problems in one message", () => {
    const r = C.csvToExpenses(HEADER + "22/11/2026,Groceries,abc,x\n2026-02-30,Food,1,y\n,,1,z\n");
    assert.equal(r.expenses.length, 0);
    assert.equal(r.errors.length, 3);
    assert.match(r.errors[0].message, /Date "22\/11\/2026".*Unknown category "Groceries".*"abc" is not a number/);
    assert.match(r.errors[0].message, /Food, Transport, Bills, Fun or Other/);
    assert.match(r.errors[1].message, /Date "2026-02-30"/);
    assert.match(r.errors[2].message, /Date is missing.*Category is missing/);
  });

  test("categories match case-insensitively and are normalised", () => {
    const r = C.csvToExpenses(HEADER + "2026-11-22, food ,1,\n2026-11-22,BILLS,1,\n");
    assert.deepEqual(r.expenses.map((e) => e.category), ["Food", "Bills"]);
  });

  test("columns can be in any order and any case; note is optional", () => {
    const r = C.csvToExpenses("Amount,DATE,Category\n4.20,2026-11-22,Fun\n");
    assert.deepEqual(r.errors, []);
    assert.deepEqual(r.expenses, [{ date: "2026-11-22", category: "Fun", amount: 4.2, note: "" }]);
  });

  test('accepts "notes" as the note column', () => {
    const r = C.csvToExpenses("date,category,amount,notes\n2026-11-22,Fun,1,hello\n");
    assert.equal(r.expenses[0].note, "hello");
  });

  test("missing required columns is one clear error", () => {
    const r = C.csvToExpenses("date,amount\n2026-11-22,5\n");
    assert.deepEqual(r.expenses, []);
    assert.equal(r.errors.length, 1);
    assert.equal(r.errors[0].line, 1);
    assert.match(r.errors[0].message, /Missing column: category/);
  });

  test("a file without a header row is rejected", () => {
    const r = C.csvToExpenses("2026-11-22,Food,5,Lunch\n");
    assert.match(r.errors[0].message, /Missing columns: date, category, amount/);
  });

  test("short rows report the missing values", () => {
    const r = C.csvToExpenses(HEADER + "2026-11-22,Food\n");
    assert.equal(r.expenses.length, 0);
    assert.match(r.errors[0].message, /Amount is missing/);
  });

  test("blank lines are skipped and line numbers stay correct", () => {
    const r = C.csvToExpenses("\n" + HEADER + "\n2026-11-22,Food,1,\n\n2026-11-22,Nope,1,\n");
    assert.equal(r.rowCount, 2);
    assert.equal(r.expenses.length, 1);
    assert.deepEqual(r.errors.map((e) => e.line), [6]);
  });

  test("line numbers account for multi-line quoted notes", () => {
    const r = C.csvToExpenses(HEADER + '2026-11-22,Food,1,"two\nlines"\n2026-11-22,Food,bad,\n');
    assert.equal(r.expenses[0].note, "two\nlines");
    assert.deepEqual(r.errors.map((e) => e.line), [4]);
  });

  test("an unclosed quote is reported instead of throwing", () => {
    const r = C.csvToExpenses(HEADER + '2026-11-22,Food,1,"oops\n2026-11-23,Food,2,\n');
    assert.deepEqual(r.expenses, []);
    assert.equal(r.errors.length, 1);
    assert.equal(r.errors[0].line, 2);
    assert.match(r.errors[0].message, /never closed/);
  });

  test("handles a BOM and Windows line endings", () => {
    const r = C.csvToExpenses("﻿date,category,amount,note\r\n2026-11-22,Food,1,a\r\n");
    assert.deepEqual(r.errors, []);
    assert.equal(r.expenses.length, 1);
  });

  test("every imported row passes the app's own validation", () => {
    const r = C.csvToExpenses(HEADER + "2026-11-22,Food,1,a\n2026-11-23,Other,99.99,b\n");
    for (const e of r.expenses) {
      assert.deepEqual(L.validateExpense(e), {});
      assert.doesNotThrow(() => L.createExpense(e, "id", 0));
    }
  });
});

