          ? 'Unknown category "' + rawCat.trim() + '" (use ' + listCategories() + ").'
          : "Category is missing.");
      }

      var amount = parseAmount(cell(f, "amount"));
      if (amount.error) problems.push(amount.error);

      if (problems.length) {
        result.errors.push({ line: rec.line, message: problems.join(" ") });
        return;
      }

      var expense = {
        date: date,
        category: category,
        amount: amount.value,
        note: unprotectFormula(cell(f, "note").trim())
      };
