const L = require('./logic.js');
const C = require('./csv.js');
const assert = require('assert');
const vm = require('vm'); const fs = require('fs');

function el(tag, id) {
  const e = { tagName: tag, id, value: '', textContent: '', hidden: false, disabled: false, children: [], attrs: {}, listeners: {},
    className: '', dateTime: '', tabIndex: -1, style: {}, parent: null, files: null,
    offsetLeft: 100, offsetTop: 40, offsetWidth: 50, clientWidth: 600,
    get classList() { const self = this; const has = c => self.className.split(' ').includes(c); return {
