/*
 * Pure budget logic: no DOM, no localStorage.
 *
 * A budget is a monthly limit per category that applies to every month,
 * stored as { Food: 300, Fun: 50, ... }. A category with no entry has no
 * budget. A budget of 0 is allowed and means "spend nothing".
 *
 * Status for a category in a month:
 *   "none"    no budget set
 *   "ok"      spent <= 80% of budget
 *   "warning" spent passes 80% of budget (more than 80%, up to 100%)
 *   "over"    spent passes 100% of budget (more than the budget)
 *
 * All comparisons are done in whole cents, so 80.00 of 100.00 is exactly
 * 80% (not a warning) and 100.00 of 100.00 is exactly 100% (a warning,
 * not over).
 *
 * Loads in the browser (window.ExpenseBudget, after logic.js) or from Node.
 */
(function (root, factory) {
  "use strict";
  if (typeof module !== "undefined" && module.exports) {
    module.exports = factory(require("./logic.js"));
  } else {
    root.ExpenseBudget = factory(root.ExpenseLogic);
  }
})(typeof globalThis !== "undefined" ? globalThis : this, function (L) {
  "use strict";

  var WARNING_PERCENT = 80;
  var STATUS = { NONE: "none", OK: "ok", WARNING: "warning", OVER: "over" };

  function hasOwn(obj, key) {
    return Object.prototype.hasOwnProperty.call(obj, key);
  }

  function isBudgetValue(v) {
    return typeof v === "number" && isFinite(v) && v >= 0;
  }

  /**
   * Keep only known categories with a usable budget (finite number >= 0),
   * rounded to cents. Returns a new object.
   */
  function normalizeBudgets(budgets) {
    var out = {};
    if (!budgets || typeof budgets !== "object" || Array.isArray(budgets)) return out;
    L.CATEGORIES.forEach(function (c) {
      if (hasOwn(budgets, c) && isBudgetValue(budgets[c])) {
        out[c] = L.toCents(budgets[c]) / 100;
      }
    });
    return out;
  }

  /** Read budgets saved as JSON; anything corrupt becomes "no budgets". */
  function parseStoredBudgets(json) {
    try {
      return normalizeBudgets(JSON.parse(json));
    } catch (e) {
      return {};
    }
  }

  /**
   * Read what the user typed in a budget box.
   * ""      -> { value: null }   (no budget)
   * "250"   -> { value: 250 }
   * "0"     -> { value: 0 }
   * "-5", "abc" -> { error }
   */
  function parseBudgetInput(raw) {
    var s = raw == null ? "" : String(raw).trim();
    if (s === "") return { value: null };
    var cents = L.toCents(s);
    if (isNaN(cents)) return { error: "Enter a number, or leave empty for no budget." };
    if (cents < 0) return { error: "Budget can't be negative." };
    return { value: cents / 100 };
  }

  /** Return new budgets with one category set, or removed when value is null. */
  function setBudget(budgets, category, value) {
    if (L.CATEGORIES.indexOf(category) === -1) {
      throw new Error("Unknown category: " + category);
    }
    var out = normalizeBudgets(budgets);
    if (value == null) {
      delete out[category];
    } else if (isBudgetValue(value)) {
      out[category] = L.toCents(value) / 100;
    } else {
      throw new Error("Invalid budget for " + category + ": " + value);
    }
    return out;
  }

  /** Status of `spent` against `budget` (null/undefined = no budget). */
  function budgetStatus(spent, budget) {
    if (budget == null || !isBudgetValue(budget)) return STATUS.NONE;
    var spentCents = Math.max(0, L.toCents(spent) || 0);
    var budgetCents = L.toCents(budget);
    if (spentCents > budgetCents) return STATUS.OVER;
    // spent / budget > 80 / 100, without dividing.
    if (spentCents * 100 > budgetCents * WARNING_PERCENT) return STATUS.WARNING;
    return STATUS.OK;
  }

  /**
   * Combine a month summary (from logic.summarizeMonth) with budgets.
   *
   * Returns {
   *   month,
   *   categories: [{ ...summary row, spent, budget, remaining, percent,
   *                  status, spentOfScale, budgetOfScale }],
   *   warnings: [rows with status "warning"],
   *   over:     [rows with status "over"],
   *   hasBudgets: whether any category has a budget,
   *   budgetTotal: sum of the budgets that are set,
   *   budgetedSpent: what was spent in categories that have a budget
   * }
   *
   * `percent` is spent as a whole-number % of budget (null when there is no
   * budget, or the budget is 0). `remaining` is budget - spent, negative when
   * over (null without a budget). `spentOfScale` / `budgetOfScale` are 0..1
   * positions on one shared scale (the largest spend or budget in the
   * month), so a chart can draw bars and budget markers together.
   */
  function budgetReport(summary, budgets) {
    var b = normalizeBudgets(budgets);
    var rows = summary.categories;

    var scaleCents = 0;
    rows.forEach(function (r) {
      scaleCents = Math.max(scaleCents, L.toCents(r.total));
      if (hasOwn(b, r.category)) scaleCents = Math.max(scaleCents, L.toCents(b[r.category]));
    });

    var budgetTotalCents = 0;
    var budgetedSpentCents = 0;

    var categories = rows.map(function (r) {
      var spentCents = L.toCents(r.total);
      var has = hasOwn(b, r.category);
      var budget = has ? b[r.category] : null;
      var budgetCents = has ? L.toCents(budget) : 0;
      if (has) {
        budgetTotalCents += budgetCents;
        budgetedSpentCents += spentCents;
      }
      var out = {};
      Object.keys(r).forEach(function (k) { out[k] = r[k]; });
      out.spent = spentCents / 100;
      out.budget = budget;
      out.remaining = has ? (budgetCents - spentCents) / 100 : null;
      out.percent = has && budgetCents > 0 ? Math.round((spentCents * 100) / budgetCents) : null;
      out.status = budgetStatus(out.spent, budget);
      out.spentOfScale = scaleCents ? spentCents / scaleCents : 0;
      out.budgetOfScale = has ? (scaleCents ? budgetCents / scaleCents : 0) : null;
      return out;
    });

    return {
      month: summary.month,
      categories: categories,
      warnings: categories.filter(function (r) { return r.status === STATUS.WARNING; }),
      over: categories.filter(function (r) { return r.status === STATUS.OVER; }),
      hasBudgets: Object.keys(b).length > 0,
      budgetTotal: budgetTotalCents / 100,
      budgetedSpent: budgetedSpentCents / 100
    };
  }

  return {
    WARNING_PERCENT: WARNING_PERCENT,
    STATUS: STATUS,
    normalizeBudgets: normalizeBudgets,
    parseStoredBudgets: parseStoredBudgets,
    parseBudgetInput: parseBudgetInput,
    setBudget: setBudget,
    budgetStatus: budgetStatus,
    budgetReport: budgetReport
  };
});

