    var bar = makeEl("span", "bar");
    // One scale for bars and budget markers; keep tiny values visible.
    bar.style.width = "max(4px, " + (row.spentOfScale * 100).toFixed(2) + "%)";
    track.appendChild(bar);
  }
  if (row.budgetOfScale != null) {
    var marker = makeEl("span", "budget-marker");
    marker.style.left = "calc(" + (row.budgetOfScale * 100).toFixed(2) + "% - 1px)";
    marker.title = "Budget " + L.formatAmount(row.budget);
    track.appendChild(marker);
  }
  el.appendChild(track);

  el.appendChild(makeEl("span", "bar-value", amountText));

  if (bText) {
    var line = makeEl("span", "bar-budget");
    if (STATUS_WORD[row.status]) line.appendChild(statusIcon(row.status));
    line.appendChild(makeEl("span", null, bText));
    el.appendChild(line);
  }

  el.summaryRow = row;
  return el;
}

function usedText(row) {
  if (row.budget == null) return "—";
  return row.percentLabel + (STATUS_WORD[row.status] ? " · " + STATUS_WORD[row.status] : "");
}

function renderTableRow(row) {
  var tr = document.createElement("tr");
  if (row.status === B.STATUS.WARNING || row.status === B.STATUS.OVER) tr.className = "is-" + row.status;
  tr.appendChild(makeEl("td", null, row.category));
  tr.appendChild(makeEl("td", null, String(row.count)));
  tr.appendChild(makeEl("td", null, L.formatAmount(row.total)));
  tr.appendChild(makeEl("td", null, formatShare(row.share)));
  tr.appendChild(makeEl("td", null, row.budget == null ? "—" : L.formatAmount(row.budget)));
  tr.appendChild(makeEl("td", null, usedText(row)));
  return tr;
}

function renderAlerts(report) {
  var rows = report.over.concat(report.warnings);
  var items = rows.map(function (row) {
    var li = makeEl("li", "budget-alert is-" + row.status);
    li.appendChild(statusIcon(row.status));
    li.appendChild(makeEl("span", null, alertText(row)));
    return li;
  });
  budgetAlertListEl.replaceChildren.apply(budgetAlertListEl, items);
  budgetAlertsEl.hidden = items.length === 0;
}

