  form.addEventListener("submit", onSubmit);

  // Clear a field's error as soon as the user edits it.
  Object.keys(fields).forEach(function (name) {
    fields[name].addEventListener("input", function () {
      document.getElementById(name + "-error").textContent = "";
      fields[name].removeAttribute("aria-invalid");
    });
  });

  // Month picker. Browsers without <input type="month"> show a text box;
  // only a complete YYYY-MM value is accepted.
  function onMonthInput() {
    if (L.isValidMonth(monthInput.value)) {
      setMonth(monthInput.value);
    } else if (monthInput.value.length >= 7) {
      monthInput.setAttribute("aria-invalid", "true");
    }
  }
  monthInput.addEventListener("input", onMonthInput);
  monthInput.addEventListener("change", onMonthInput);
  monthInput.addEventListener("blur", function () {
    // Cleared or half-typed: put the selected month back.
    if (!L.isValidMonth(monthInput.value)) renderSummary();
  });
  prevMonthBtn.addEventListener("click", function () {
    setMonth(L.shiftMonth(selectedMonth, -1));
  });
  nextMonthBtn.addEventListener("click", function () {
    setMonth(L.shiftMonth(selectedMonth, 1));
  });

  barChartEl.addEventListener("mouseover", function (e) {
    var row = rowFromEvent(e);
    if (row && row !== activeRow) showTooltip(row);
  });
  barChartEl.addEventListener("mouseleave", hideTooltip);
  barChartEl.addEventListener("focusin", function (e) {
    var row = rowFromEvent(e);
    if (row) showTooltip(row);
  });
  barChartEl.addEventListener("focusout", hideTooltip);
  barChartEl.addEventListener("keydown", function (e) {
    if (e.key === "Escape") hideTooltip();
  });

  exportBtn.addEventListener("click", exportCsv);
  importInput.addEventListener("change", onImportFile);

  // Stay in sync if the tracker is open in another tab.
  window.addEventListener("storage", function (e) {
    if (e.key === STORAGE_KEY) {
      expenses = loadExpenses();
      render();
    }
  });

  render();
})();

