.bar-row.is-over {
  background: var(--alert-bg);
  box-shadow: inset 3px 0 0 var(--status-critical);
}

.bar-row.is-over.is-active {
  background: #fae4e4;
}

.bar-budget {
  grid-column: 2 / -1;
  display: flex;
  align-items: center;
  gap: 6px;
  margin: -4px 0 6px;
  font-size: 0.8rem;
  color: var(--muted);
}

.bar-row.is-warning .bar-budget {
  color: var(--text);
}

.bar-row.is-over .bar-budget {
  color: var(--alert-text);
