"use strict";

const { describe, test } = require("node:test");
const assert = require("node:assert/strict");
const L = require("../logic.js");
const B = require("../budget.js");

const { NONE, OK, WARNING, OVER } = B.STATUS;

function exp(id, amount, category, date) {
  return L.createExpense({ amount, category, date }, id, 0);
}

describe("budgetStatus", () => {
  test("no budget means no status", () => {
    assert.equal(B.budgetStatus(50, null), NONE);
    assert.equal(B.budgetStatus(50, undefined), NONE);
    assert.equal(B.budgetStatus(50, NaN), NONE);
    assert.equal(B.budgetStatus(50, -10), NONE);
  });

  test("up to and including 80% is ok", () => {
    assert.equal(B.budgetStatus(0, 100), OK);
    assert.equal(B.budgetStatus(50, 100), OK);
    assert.equal(B.budgetStatus(80, 100), OK, "exactly 80% has not passed 80%");
    assert.equal(B.budgetStatus(79.99, 100), OK);
  });

  test("passing 80% is a warning, up to and including 100%", () => {
    assert.equal(B.budgetStatus(80.01, 100), WARNING);
    assert.equal(B.budgetStatus(90, 100), WARNING);
    assert.equal(B.budgetStatus(100, 100), WARNING, "exactly 100% is not above 100%");
  });

  test("above 100% is over", () => {
    assert.equal(B.budgetStatus(100.01, 100), OVER);
    assert.equal(B.budgetStatus(250, 100), OVER);
  });

  test("thresholds are exact in cents, with no float surprises", () => {
    // 0.1 + 0.2 + 0.5 = 0.8000000000000002 in floating point
    assert.equal(B.budgetStatus(0.1 + 0.2 + 0.5, 1), OK);
    // 0.7 + 0.1 + 0.2 = 0.9999999999999999
    assert.equal(B.budgetStatus(0.7 + 0.1 + 0.2, 1), WARNING);
    // 80% of an odd budget: 0.8 * 33.33 = 26.664
    assert.equal(B.budgetStatus(26.66, 33.33), OK);
    assert.equal(B.budgetStatus(26.67, 33.33), WARNING);
    assert.equal(B.budgetStatus(33.33, 33.33), WARNING);
    assert.equal(B.budgetStatus(33.34, 33.33), OVER);
  });

  test("a zero budget is ok until anything is spent", () => {
    assert.equal(B.budgetStatus(0, 0), OK);
    assert.equal(B.budgetStatus(0.01, 0), OVER);
  });

  test("tiny budgets", () => {
    assert.equal(B.budgetStatus(0.01, 0.01), WARNING);
    assert.equal(B.budgetStatus(0.02, 0.01), OVER);
  });
});

describe("percentLabel", () => {
  test("rounds down so it never overstates", () => {
    assert.equal(B.percentLabel(0, 100), "0%");
    assert.equal(B.percentLabel(45, 100), "45%");
    assert.equal(B.percentLabel(99.99, 100), "99%");
    assert.equal(B.percentLabel(80, 100), "80%");
    assert.equal(B.percentLabel(100, 100), "100%");
    assert.equal(B.percentLabel(250, 100), "250%");
  });

  test("never contradicts the status just past a threshold", () => {
    assert.equal(B.percentLabel(80.4, 100), ">80%");
    assert.equal(B.budgetStatus(80.4, 100), WARNING);
    assert.equal(B.percentLabel(100.5, 100), ">100%");
    assert.equal(B.budgetStatus(100.5, 100), OVER);
    assert.equal(B.percentLabel(81, 100), "81%");
  });

  test("zero and missing budgets", () => {
    assert.equal(B.percentLabel(0, 0), "0%");
    assert.equal(B.percentLabel(5, 0), "over 0");
    assert.equal(B.percentLabel(5, null), null);
  });
});

describe("parseBudgetInput", () => {
  test("empty means no budget", () => {
    assert.deepEqual(B.parseBudgetInput(""), { value: null });
    assert.deepEqual(B.parseBudgetInput("   "), { value: null });
    assert.deepEqual(B.parseBudgetInput(null), { value: null });
    assert.deepEqual(B.parseBudgetInput(undefined), { value: null });
  });

  test("numbers, including zero, rounded to cents", () => {
    assert.deepEqual(B.parseBudgetInput("250"), { value: 250 });
    assert.deepEqual(B.parseBudgetInput(" 99.5 "), { value: 99.5 });
    assert.deepEqual(B.parseBudgetInput("0"), { value: 0 });
    assert.deepEqual(B.parseBudgetInput("10.005"), { value: 10.01 });
    assert.deepEqual(B.parseBudgetInput(42), { value: 42 });
  });

  test("rejects negatives and non-numbers", () => {
    assert.match(B.parseBudgetInput("-5").error, /negative/);
    for (const bad of ["abc", "12abc", "1,000"]) {
      assert.match(B.parseBudgetInput(bad).error, /number/, bad);
    }
  });
});

describe("normalizeBudgets / parseStoredBudgets", () => {
  test("keeps known categories with usable values", () => {
    assert.deepEqual(
      B.normalizeBudgets({ Food: 300, Fun: 0, Bills: 10.005, Nope: 5, Transport: -1, Other: "50" }),
      { Food: 300, Fun: 0, Bills: 10.01 });
  });

  test("anything that isn't an object becomes empty", () => {
    for (const bad of [null, undefined, 5, "x", [1, 2]]) {
      assert.deepEqual(B.normalizeBudgets(bad), {});
    }
  });

  test("ignores inherited properties", () => {
    const proto = { Food: 100 };
    assert.deepEqual(B.normalizeBudgets(Object.create(proto)), {});
  });

  test("corrupt storage becomes empty", () => {
    assert.deepEqual(B.parseStoredBudgets("not json"), {});
    assert.deepEqual(B.parseStoredBudgets(""), {});
    assert.deepEqual(B.parseStoredBudgets("[1]"), {});
    assert.deepEqual(B.parseStoredBudgets('{"Food":120,"Fun":"x"}'), { Food: 120 });
  });
});

describe("setBudget", () => {
  test("sets and removes without mutating", () => {
    const start = { Food: 100 };
    const a = B.setBudget(start, "Fun", 50);
    assert.deepEqual(a, { Food: 100, Fun: 50 });
    assert.deepEqual(start, { Food: 100 });
    assert.deepEqual(B.setBudget(a, "Food", null), { Fun: 50 });
    assert.deepEqual(B.setBudget(a, "Food", 0), { Food: 0, Fun: 50 });
  });

  test("rejects unknown categories and bad values", () => {
    assert.throws(() => B.setBudget({}, "Groceries", 10), /Unknown category/);
    assert.throws(() => B.setBudget({}, "Food", -1), /Invalid budget/);
    assert.throws(() => B.setBudget({}, "Food", NaN), /Invalid budget/);
  });
});

describe("budgetReport", () => {
  const expenses = [
    exp("1", 85, "Food", "2026-11-03"),       // Food 85 of 100 -> warning
    exp("2", 130, "Bills", "2026-11-01"),     // Bills 130 of 120 -> over
    exp("3", 20, "Fun", "2026-11-09"),        // Fun 20 of 50 -> ok
    exp("4", 15, "Transport", "2026-11-09"),  // Transport, no budget
    exp("5", 999, "Food", "2026-10-31")       // other month: ignored
  ];
  const budgets = { Food: 100, Bills: 120, Fun: 50, Other: 0 };

  function report(month = "2026-11", b = budgets) {
    return B.budgetReport(L.summarizeMonth(expenses, month), b);
  }

  test("status per category for the month", () => {
    const r = report();
    assert.equal(r.month, "2026-11");
    assert.deepEqual(r.categories.map((c) => [c.category, c.status]), [
      ["Food", WARNING], ["Transport", NONE], ["Bills", OVER], ["Fun", OK], ["Other", OK]
    ]);
    assert.deepEqual(r.warnings.map((c) => c.category), ["Food"]);
    assert.deepEqual(r.over.map((c) => c.category), ["Bills"]);
  });

  test("spent, remaining and percent", () => {
    const [food, transport, bills, fun, other] = report().categories;
    assert.deepEqual([food.spent, food.budget, food.remaining, food.percent, food.percentLabel], [85, 100, 15, 85, "85%"]);
    assert.deepEqual([bills.spent, bills.budget, bills.remaining, bills.percent], [130, 120, -10, 108]);
    assert.deepEqual([fun.remaining, fun.percent], [30, 40]);
    assert.deepEqual([transport.budget, transport.remaining, transport.percent, transport.percentLabel], [null, null, null, null]);
    assert.deepEqual([other.budget, other.remaining, other.percent, other.percentLabel], [0, 0, null, "0%"]);
  });

  test("keeps the month summary fields", () => {
    const food = report().categories[0];
    assert.equal(food.total, 85);
    assert.equal(food.count, 1);
    assert.ok(food.share > 0);
  });

  test("totals cover only categories with a budget", () => {
    const r = report();
    assert.equal(r.hasBudgets, true);
    assert.equal(r.budgetTotal, 270);
    assert.equal(r.budgetedSpent, 235, "Transport has no budget so its 15 is left out");
  });

  test("bars and budget markers share one scale", () => {
    const [food, transport, bills, fun] = report().categories;
    // The largest value is Bills' spend (130).
    assert.equal(bills.spentOfScale, 1);
    assert.equal(bills.budgetOfScale, 120 / 130);
    assert.equal(food.spentOfScale, 85 / 130);
    assert.equal(food.budgetOfScale, 100 / 130);
    assert.equal(fun.budgetOfScale, 50 / 130);
    assert.equal(transport.budgetOfScale, null);
  });

  test("a budget bigger than any spend sets the scale", () => {
    const r = B.budgetReport(L.summarizeMonth(expenses, "2026-11"), { Fun: 400 });
    const fun = r.categories[3];
    assert.equal(fun.budgetOfScale, 1);
    assert.equal(fun.spentOfScale, 20 / 400);
  });

  test("an empty month with budgets: everything ok, nothing spent", () => {
    const r = report("2020-01");
    assert.ok(r.categories.every((c) => c.spent === 0 && c.spentOfScale === 0));
    assert.deepEqual(r.categories.filter((c) => c.status !== NONE).map((c) => c.status), [OK, OK, OK, OK]);
    assert.equal(r.categories[0].budgetOfScale, 100 / 120);
    assert.equal(r.categories[4].budgetOfScale, 0);
    assert.deepEqual(r.warnings, []);
    assert.deepEqual(r.over, []);
  });

  test("no budgets at all", () => {
    const r = report("2026-11", {});
    assert.equal(r.hasBudgets, false);
    assert.equal(r.budgetTotal, 0);
    assert.ok(r.categories.every((c) => c.status === NONE && c.budgetOfScale === null));
    assert.equal(r.categories[2].spentOfScale, 1);
  });

  test("no budgets and no spending: no divide by zero", () => {
    const r = report("2020-01", {});
    assert.ok(r.categories.every((c) => c.spentOfScale === 0));
  });

  test("corrupt budgets are ignored", () => {
    const r = report("2026-11", { Food: "lots", Bills: -5, Fun: 50 });
    assert.deepEqual(r.categories.map((c) => c.status), [NONE, NONE, NONE, OK, NONE]);
  });

  test("adding one more expense can move a category from warning to over", () => {
    const more = expenses.concat([exp("6", 15.01, "Food", "2026-11-20")]);
    const food = B.budgetReport(L.summarizeMonth(more, "2026-11"), budgets).categories[0];
    assert.equal(food.status, OVER);
    assert.equal(food.remaining, -0.01);
    assert.equal(food.percentLabel, ">100%");
  });
});

