const L = require('./logic.js');
const C = require('./csv.js');
const B = require('./budget.js');
const assert = require('assert');
const vm = require('vm'); const fs = require('fs');

function el(tag, id) {
  const e = { tagName: tag, id, value: '', textContent: '', hidden: false, disabled: false, children: [], attrs: {}, listeners: {},
    className: '', title: '', tabIndex: -1, style: {}, parent: null, validity: { badInput: false },
    offsetLeft: 100, offsetTop: 40, offsetWidth: 50, clientWidth: 600,
    get classList() { const self = this; const has = c => self.className.split(' ').includes(c); return {
      add(c) { if (!has(c)) self.className = (self.className + ' ' + c).trim(); },
      remove(c) { self.className = self.className.split(' ').filter(x => x !== c).join(' '); },
      toggle(c, on) { if (on) this.add(c); else this.remove(c); }, contains: has }; },
    appendChild(c) { c.parent = this; this.children.push(c); if (c.id) els[c.id] = c; return c; },
    replaceChildren(...k) { k.forEach(c => c.parent = this); this.children = k; },
    remove() {}, click() {},
    setAttribute(k, v) { this.attrs[k] = String(v); }, removeAttribute(k) { delete this.attrs[k]; },
    addEventListener(t, f) { this.listeners[t] = f; }, focus() { focused = this; },
    querySelector(sel) { const cls = sel.slice(1); const walk = n => { for (const c of n.children) { if (c.className.split(' ').includes(cls)) return c; const r = walk(c); if (r) return r; } return null; }; return walk(this); },
    closest() { return null; } };
  return e;
}
let focused = null;
const els = {}; const getEl = id => els[id] || (els[id] = el('div', id));
const store = {};
const month = L.monthOf(L.toISODate(new Date()));
store['expense-tracker.expenses'] = JSON.stringify([
  L.createExpense({ amount: 85, category: 'Food', date: month + '-01' }, 'a', 1),
  L.createExpense({ amount: 130, category: 'Bills', date: month + '-02' }, 'b', 2),
  L.createExpense({ amount: 10, category: 'Fun', date: month + '-03' }, 'c', 3)
]);
store['expense-tracker.budgets'] = JSON.stringify({ Food: 100, Bills: 120 });
const ctx = { console, Date, Math, JSON, Object, String, Number, Array, Promise, setTimeout: () => {},
  document: { getElementById: getEl, createElement: t => el(t), body: el('body') },
  localStorage: { getItem: k => store[k] ?? null, setItem: (k, v) => { store[k] = String(v); } },
  window: { addEventListener() {}, ExpenseLogic: L, ExpenseCSV: C, ExpenseBudget: B } };
vm.createContext(ctx);
vm.runInContext(fs.readFileSync('./app.js', 'utf8'), ctx);

const rows = () => getEl('bar-chart').children;
const row = name => rows().find(r => r.children[0].textContent === name);
const budgetLine = r => { const l = r.children.find(c => c.className === 'bar-budget'); return l ? l.children.map(c => c.textContent).join('') : null; };
const alerts = () => getEl('budget-alert-list').children.map(li => li.className + ' | ' + li.children[1].textContent);

// Fields built and filled from storage
assert.strictEqual(getEl('budget-fields').children.length, 5);
assert.strictEqual(getEl('budget-food').value, '100.00');
assert.strictEqual(getEl('budget-bills').value, '120.00');
assert.strictEqual(getEl('budget-fun').value, '');

// Statuses on the chart
assert.ok(row('Food').className.includes('is-warning'));
assert.ok(row('Bills').className.includes('is-over'));
assert.ok(row('Fun').className.includes('is-none'));
assert.strictEqual(budgetLine(row('Food')), '!85% of 100.00 budget · 15.00 left');
assert.strictEqual(budgetLine(row('Bills')), '!Over budget by 10.00 (108% of 120.00)');
assert.strictEqual(budgetLine(row('Fun')), null);
assert.strictEqual(row('Food').children[1].children[1].style.left, 'calc(76.92% - 1px)');
assert.strictEqual(row('Bills').children[1].children[0].style.width, 'max(4px, 100.00%)');
assert.ok(row('Bills').attrs['aria-label'].includes('Over budget: Over budget by 10.00'));
assert.deepStrictEqual(alerts(), [
  'budget-alert is-over | Bills is over budget by 10.00 (108% of 120.00).',
  'budget-alert is-warning | Food has used 85% of its 100.00 budget (15.00 left).'
]);
assert.strictEqual(getEl('budget-alerts').hidden, false);

// Table view
const t = getEl('summary-table').children.map(tr => tr.children.map(td => td.textContent));
assert.deepStrictEqual(t[0], ['Food', '1', '85.00', '37%', '100.00', '85% · Warning']);
assert.deepStrictEqual(t[1], ['Transport', '0', '0.00', '0%', '—', '—']);
assert.deepStrictEqual(t[2], ['Bills', '1', '130.00', '58%', '120.00', '108% · Over budget']);
assert.deepStrictEqual(t[5], ['Total', '3', '225.00', '100%', '220.00', '97% of budgeted']);

// Tooltip includes budget
getEl('bar-chart').listeners.focusin({ target: row('Food') });
assert.strictEqual(getEl('chart-tooltip').children[2].textContent, 'Warning: 85% of 100.00 budget · 15.00 left');

// Invalid budget input is rejected, nothing saved
getEl('budget-fun').value = '-3';
getEl('budget-form').listeners.submit({ preventDefault() {} });
assert.strictEqual(getEl('budget-fun-error').textContent, "Budget can't be negative.");
assert.strictEqual(getEl('budget-fun').attrs['aria-invalid'], 'true');
assert.strictEqual(focused, getEl('budget-fun'));
assert.strictEqual(store['expense-tracker.budgets'], JSON.stringify({ Food: 100, Bills: 120 }));
getEl('budget-fun').validity = { badInput: true }; getEl('budget-fun').value = '';
getEl('budget-form').listeners.submit({ preventDefault() {} });
assert.ok(getEl('budget-fun-error').textContent.includes('Enter a number'));
getEl('budget-fun').validity = { badInput: false };

// Valid save: raise Bills, add Fun, clear Food
getEl('budget-fun').value = '12'; getEl('budget-bills').value = '200'; getEl('budget-food').value = '';
getEl('budget-fun').listeners.input();
assert.strictEqual(getEl('budget-fun-error').textContent, '');
getEl('budget-form').listeners.submit({ preventDefault() {} });
assert.strictEqual(getEl('budget-saved').textContent, 'Budgets saved.');
assert.deepStrictEqual(JSON.parse(store['expense-tracker.budgets']), { Bills: 200, Fun: 12 });
assert.strictEqual(getEl('budget-fun').value, '12.00');
assert.ok(row('Food').className.includes('is-none'));
assert.ok(row('Bills').className.includes('is-ok'));
assert.ok(row('Fun').className.includes('is-warning'));
assert.deepStrictEqual(alerts(), ['budget-alert is-warning | Fun has used 83% of its 12.00 budget (2.00 left).']);

// Adding an expense pushes Fun over
const add = (amount, category, date) => { getEl('amount').value = amount; getEl('category').value = category; getEl('date').value = date; getEl('expense-form').listeners.submit({ preventDefault() {} }); };
add('2.01', 'Fun', month + '-10');
assert.ok(row('Fun').className.includes('is-over'));
assert.deepStrictEqual(alerts(), ['budget-alert is-over | Fun is over budget by 0.01 (>100% of 12.00).']);

// Empty month with budgets: chart still shows markers, no alerts
getEl('prev-month').listeners.click();
assert.strictEqual(getEl('summary-empty').hidden, false);
assert.strictEqual(getEl('chart').hidden, false);
assert.strictEqual(getEl('budget-alerts').hidden, true);
assert.strictEqual(budgetLine(row('Bills')), '0% of 200.00 budget');

// Clear all budgets: back to step-2 behaviour
['food', 'transport', 'bills', 'fun', 'other'].forEach(c => { getEl('budget-' + c).value = ''; });
getEl('budget-form').listeners.submit({ preventDefault() {} });
assert.deepStrictEqual(JSON.parse(store['expense-tracker.budgets']), {});
assert.strictEqual(getEl('chart').hidden, true);
getEl('next-month').listeners.click();
assert.ok(rows().every(r => r.className.includes('is-none') && budgetLine(r) === null));
assert.strictEqual(getEl('budget-alerts').hidden, true);
console.log('budget UI smoke test passed');

