/*
 * Pure expense logic: no DOM, no localStorage, no clock, no randomness.
 * Every function returns a new value and never mutates its inputs,
 * so this file can be loaded in the browser or required from Node tests.
 */
(function (root) {
  "use strict";

  var CATEGORIES = ["Food", "Transport", "Bills", "Fun", "Other"];

  var ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

  /** Convert an amount (number or numeric string) to integer cents, or NaN. */
  function toCents(amount) {
    var n = typeof amount === "string" ? Number(amount.trim()) : amount;
    if (typeof n !== "number" || !isFinite(n) || (typeof amount === "string" && amount.trim() === "")) {
      return NaN;
    }
    // Shift the decimal point in the number's text form, so 1.005 becomes
    // 100.5 (and rounds to 101) instead of 100.49999… from n * 100.
    var s = String(n);
    return s.indexOf("e") === -1 ? Math.round(Number(s + "e2")) : Math.round(n * 100);
  }

  /** True if `str` is a real calendar date in YYYY-MM-DD form. */
  function isValidDate(str) {
    if (typeof str !== "string" || !ISO_DATE.test(str)) return false;
    var parts = str.split("-").map(Number);
    var d = new Date(Date.UTC(parts[0], parts[1] - 1, parts[2]));
    return (
      d.getUTCFullYear() === parts[0] &&
      d.getUTCMonth() === parts[1] - 1 &&
      d.getUTCDate() === parts[2]
    );
  }

  /**
   * Check raw form input. Returns an object of field -> message.
   * An empty object means the input is valid.
   */
  function validateExpense(input) {
    var errors = {};
    input = input || {};

    var cents = toCents(input.amount);
    if (isNaN(cents)) {
      errors.amount = "Enter an amount.";
    } else if (cents <= 0) {
      errors.amount = "Amount must be greater than 0.";
    }

    if (CATEGORIES.indexOf(input.category) === -1) {
      errors.category = "Choose a category.";
    }

    if (!isValidDate(input.date)) {
      errors.date = "Enter a valid date.";
    }

    if (input.note != null && typeof input.note !== "string") {
      errors.note = "Note must be text.";
    }

    return errors;
  }

  /**
   * Build a normalised expense record from raw input.
   * `id` and `createdAt` are passed in (rather than generated here) to keep
   * this function pure. Throws if the input is invalid.
   */
  function createExpense(input, id, createdAt) {
    var errors = validateExpense(input);
    var fields = Object.keys(errors);
    if (fields.length > 0) {
      throw new Error("Invalid expense: " + fields.map(function (f) { return errors[f]; }).join(" "));
    }
    return {
      id: String(id),
      amount: toCents(input.amount) / 100,
      category: input.category,
      date: input.date,
      note: (input.note || "").trim(),
      createdAt: Number(createdAt) || 0
    };
  }

  /** Sum of all expense amounts, computed in cents to avoid float drift. */
  function calculateTotal(expenses) {
    var cents = (expenses || []).reduce(function (sum, e) {
      var c = toCents(e && e.amount);
      return isNaN(c) ? sum : sum + c;
    }, 0);
    return cents / 100;
  }

  /**
   * Newest first: later `date` first; for the same date, the one added
   * later (`createdAt`) comes first. Returns a new array.
   */
  function sortNewestFirst(expenses) {
    return (expenses || []).slice().sort(function (a, b) {
      if (a.date !== b.date) return a.date < b.date ? 1 : -1;
      return (b.createdAt || 0) - (a.createdAt || 0);
    });
  }

  /** Return a new array with `expense` appended. */
  function addExpense(expenses, expense) {
    return (expenses || []).concat([expense]);
  }

  /** Format a number as money with two decimals, e.g. 1234.5 -> "1,234.50". */
  function formatAmount(amount) {
    var cents = toCents(amount);
    if (isNaN(cents)) cents = 0;
    var negative = cents < 0;
    cents = Math.abs(cents);
    var whole = String(Math.floor(cents / 100)).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    var frac = String(cents % 100).padStart(2, "0");
    return (negative ? "-" : "") + whole + "." + frac;
  }

  /** Format a Date as local YYYY-MM-DD (for the date input default). */
  function toISODate(date) {
    var y = date.getFullYear();
    var m = String(date.getMonth() + 1).padStart(2, "0");
    var d = String(date.getDate()).padStart(2, "0");
    return y + "-" + m + "-" + d;
  }

  /**
   * Turn whatever was stored (possibly corrupt) into a clean array of
   * valid expenses. Invalid entries are dropped.
   */
  function parseStoredExpenses(json) {
    var data;
    try {
      data = JSON.parse(json);
    } catch (e) {
      return [];
    }
    if (!Array.isArray(data)) return [];
    return data.filter(function (e) {
      return e && typeof e === "object" && e.id != null &&
        Object.keys(validateExpense(e)).length === 0;
    }).map(function (e) {
      return createExpense(e, e.id, e.createdAt);
    });
  }

  // ---- Monthly summary ----------------------------------------------------

  var ISO_MONTH = /^\d{4}-(0[1-9]|1[0-2])$/;

  /** True if `str` is a month in YYYY-MM form. */
  function isValidMonth(str) {
    return typeof str === "string" && ISO_MONTH.test(str);
  }

  /** "2026-11-22" -> "2026-11". */
  function monthOf(isoDate) {
    return String(isoDate).slice(0, 7);
  }

  /** Move a YYYY-MM month by `delta` months, e.g. ("2026-01", -1) -> "2025-12". */
  function shiftMonth(month, delta) {
    var parts = month.split("-").map(Number);
    var index = parts[0] * 12 + (parts[1] - 1) + delta;
    var y = Math.floor(index / 12);
    var m = index - y * 12 + 1;
    return String(y).padStart(4, "0") + "-" + String(m).padStart(2, "0");
  }

  /** Expenses whose date falls in the given YYYY-MM month. Returns a new array. */
  function filterByMonth(expenses, month) {
    return (expenses || []).filter(function (e) {
      return e && monthOf(e.date) === month;
    });
  }

  /**
   * Totals per category for one month.
   * Every category is always present, in CATEGORIES order (so the chart's
   * rows don't jump around between months). `share` is the fraction of the
   * month's total (0..1); `ofMax` is the fraction of the largest category,
   * which is what a bar's length is drawn against.
   */
  function summarizeMonth(expenses, month) {
    var inMonth = filterByMonth(expenses, month);
    var centsByCat = {};
    var countByCat = {};
    CATEGORIES.forEach(function (c) { centsByCat[c] = 0; countByCat[c] = 0; });

    inMonth.forEach(function (e) {
      var c = toCents(e.amount);
      if (!isNaN(c) && Object.prototype.hasOwnProperty.call(centsByCat, e.category)) {
        centsByCat[e.category] += c;
        countByCat[e.category] += 1;
      }
    });

    var totalCents = 0;
    var maxCents = 0;
    CATEGORIES.forEach(function (c) {
      totalCents += centsByCat[c];
      if (centsByCat[c] > maxCents) maxCents = centsByCat[c];
    });

    return {
      month: month,
      count: inMonth.length,
      total: totalCents / 100,
      categories: CATEGORIES.map(function (c) {
        return {
          category: c,
          total: centsByCat[c] / 100,
          count: countByCat[c],
          share: totalCents ? centsByCat[c] / totalCents : 0,
          ofMax: maxCents ? centsByCat[c] / maxCents : 0
        };
      })
    };
  }

  // ---- Import merge -------------------------------------------------------

  /** What makes two expenses "the same" for import: date, category, amount, note. */
  function expenseKey(e) {
    return [e.date, e.category, toCents(e.amount), (e.note || "").trim()].join("\u0000");
  }

  /**
   * Add `incoming` expenses to `existing`, skipping ones already present.
   * Matching counts copies: if `existing` has one "coffee 3.00 on May 1"
   * and `incoming` has two, one is skipped and one is added. So
   * re-importing an export adds nothing, but genuine repeats are kept.
   * Returns { expenses, added, skipped } (new arrays; inputs untouched).
   */
  function mergeExpenses(existing, incoming) {
    var counts = {};
    (existing || []).forEach(function (e) {
      var k = expenseKey(e);
      counts[k] = (counts[k] || 0) + 1;
    });

    var added = [];
    var skipped = [];
    (incoming || []).forEach(function (e) {
      var k = expenseKey(e);
      if (counts[k] > 0) {
        counts[k] -= 1;
        skipped.push(e);
      } else {
        added.push(e);
      }
    });

    return {
      expenses: (existing || []).concat(added),
      added: added,
      skipped: skipped
    };
  }

  var api = {
    CATEGORIES: CATEGORIES,
    mergeExpenses: mergeExpenses,
    isValidMonth: isValidMonth,
    monthOf: monthOf,
    shiftMonth: shiftMonth,
    filterByMonth: filterByMonth,
    summarizeMonth: summarizeMonth,
    toCents: toCents,
    isValidDate: isValidDate,
    validateExpense: validateExpense,
    createExpense: createExpense,
    calculateTotal: calculateTotal,
    sortNewestFirst: sortNewestFirst,
    addExpense: addExpense,
    formatAmount: formatAmount,
    toISODate: toISODate,
    parseStoredExpenses: parseStoredExpenses
  };

  if (typeof module !== "undefined" && module.exports) {
    module.exports = api;
  } else {
    root.ExpenseLogic = api;
  }
})(typeof globalThis !== "undefined" ? globalThis : this);

