/*
 * Browser glue: DOM, events and localStorage.
 * All calculations live in logic.js (window.ExpenseLogic) and all CSV
 * reading/writing in csv.js (window.ExpenseCSV), budget rules in budget.js
 * (window.ExpenseBudget).
 */
(function () {
  "use strict";

  var L = window.ExpenseLogic;
  var STORAGE_KEY = "expense-tracker.expenses";

  var form = document.getElementById("expense-form");
  var amountInput = document.getElementById("amount");
  var categoryInput = document.getElementById("category");
  var dateInput = document.getElementById("date");
  var noteInput = document.getElementById("note");
  var listEl = document.getElementById("expense-list");
  var totalEl = document.getElementById("total");
  var countEl = document.getElementById("count");
  var emptyEl = document.getElementById("empty");

  var monthInput = document.getElementById("month");
  var prevMonthBtn = document.getElementById("prev-month");
  var nextMonthBtn = document.getElementById("next-month");
  var monthLabelEl = document.getElementById("month-label");
  var monthTotalEl = document.getElementById("month-total");
  var monthCountEl = document.getElementById("month-count");
  var summaryEmptyEl = document.getElementById("summary-empty");
  var chartEl = document.getElementById("chart");
  var barChartEl = document.getElementById("bar-chart");
  var tooltipEl = document.getElementById("chart-tooltip");
  var tableViewEl = document.getElementById("table-view");
  var summaryTableEl = document.getElementById("summary-table");

  var C = window.ExpenseCSV;
  var importInput = document.getElementById("import-file");
  var exportBtn = document.getElementById("export-btn");
  var csvStatusEl = document.getElementById("csv-status");
  var csvStatusTextEl = document.getElementById("csv-status-text");
  var csvErrorsEl = document.getElementById("csv-errors");
  var MAX_IMPORT_BYTES = 5 * 1024 * 1024;
  var MAX_ERRORS_SHOWN = 10;

  var B = window.ExpenseBudget;
  var BUDGET_KEY = "expense-tracker.budgets";
  var budgetForm = document.getElementById("budget-form");
  var budgetFieldsEl = document.getElementById("budget-fields");
  var budgetSavedEl = document.getElementById("budget-saved");
  var budgetAlertsEl = document.getElementById("budget-alerts");
  var budgetAlertListEl = document.getElementById("budget-alert-list");
  var budgetInputs = {};   // category -> <input>
  var budgetErrors = {};   // category -> error <p>

  var selectedMonth = L.monthOf(L.toISODate(new Date()));

  var fields = {
    amount: amountInput,
    category: categoryInput,
    date: dateInput,
    note: noteInput
  };

  // ---- Storage ------------------------------------------------------------

  function loadExpenses() {
    try {
      return L.parseStoredExpenses(localStorage.getItem(STORAGE_KEY) || "[]");
    } catch (e) {
      // localStorage can be unavailable (e.g. blocked by browser settings).
      return [];
    }
  }

  function saveExpenses(list) {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(list));
      return true;
    } catch (e) {
      return false;
    }
  }

  function loadBudgets() {
    try {
      return B.parseStoredBudgets(localStorage.getItem(BUDGET_KEY) || "{}");
    } catch (e) {
      return {};
    }
  }

  function saveBudgets(b) {
    try {
      localStorage.setItem(BUDGET_KEY, JSON.stringify(b));
      return true;
    } catch (e) {
      return false;
    }
  }

  var idCounter = 0;
  function makeId() {
    idCounter += 1;
    return Date.now().toString(36) + "-" + idCounter.toString(36) + "-" +
      Math.random().toString(36).slice(2, 8);
  }

  // ---- Rendering ----------------------------------------------------------

  function formatDisplayDate(iso) {
    var p = iso.split("-").map(Number);
    return new Date(p[0], p[1] - 1, p[2]).toLocaleDateString(undefined, {
      year: "numeric",
      month: "short",
      day: "numeric"
    });
  }

  function renderExpense(expense) {
    var li = document.createElement("li");
    li.className = "expense";

    var main = document.createElement("div");
    main.className = "expense-main";

    var badge = document.createElement("span");
    badge.className = "badge badge-" + expense.category.toLowerCase();
    badge.textContent = expense.category;
    main.appendChild(badge);

    if (expense.note) {
      var note = document.createElement("span");
      note.className = "expense-note";
      note.textContent = expense.note; // textContent: never inject HTML
      main.appendChild(note);
    }

    var amount = document.createElement("span");
    amount.className = "expense-amount";
    amount.textContent = L.formatAmount(expense.amount);

    var meta = document.createElement("time");
    meta.className = "expense-meta";
    meta.dateTime = expense.date;
    meta.textContent = formatDisplayDate(expense.date);

    li.appendChild(main);
    li.appendChild(amount);
    li.appendChild(meta);
    return li;
  }

  function render() {
    var sorted = L.sortNewestFirst(expenses);

    listEl.replaceChildren.apply(listEl, sorted.map(renderExpense));
    totalEl.textContent = L.formatAmount(L.calculateTotal(expenses));
    countEl.textContent = sorted.length ? "(" + sorted.length + ")" : "";
    emptyEl.hidden = sorted.length > 0;
    exportBtn.disabled = sorted.length === 0;

    renderSummary();
  }

  // ---- CSV import / export ------------------------------------------------

  function showCsvStatus(message, errors, isError) {
    csvStatusTextEl.textContent = message;
    var items = (errors || []).slice(0, MAX_ERRORS_SHOWN).map(function (err) {
      return makeEl("li", null, (err.line ? "Line " + err.line + ": " : "") + err.message);
    });
    if (errors && errors.length > MAX_ERRORS_SHOWN) {
      items.push(makeEl("li", null, "…and " + (errors.length - MAX_ERRORS_SHOWN) + " more."));
    }
    csvErrorsEl.replaceChildren.apply(csvErrorsEl, items);
    csvStatusEl.classList.toggle("is-error", !!isError);
    csvStatusEl.hidden = false;
  }

  function exportCsv() {
    if (!expenses.length) return;
    var filename = "expenses-" + L.toISODate(new Date()) + ".csv";
    // The BOM makes Excel read non-ASCII notes as UTF-8.
    var blob = new Blob(["﻿" + C.expensesToCSV(expenses)], { type: "text/csv;charset=utf-8" });
    var url = URL.createObjectURL(blob);
    var a = document.createElement("a");
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(function () { URL.revokeObjectURL(url); }, 1000);
    showCsvStatus("Exported " + plural(expenses.length, "expense") + " to " + filename + ".");
  }

  /** Apply parsed CSV text to the list. Returns nothing; reports via status. */
  function importCsvText(text) {
    var parsed = C.csvToExpenses(text);
    var base = Date.now();
    var n = parsed.expenses.length;
    // Earlier rows count as newer, matching the newest-first export order.
    var incoming = parsed.expenses.map(function (input, i) {
      return L.createExpense(input, makeId(), base + (n - i));
    });

    var merged = L.mergeExpenses(expenses, incoming);
    var bad = parsed.errors.length;
    var parts = [];

    if (merged.added.length) {
      expenses = merged.expenses;
      var saved = saveExpenses(expenses);
      render();
      parts.push("Imported " + plural(merged.added.length, "expense") + ".");
      if (!saved) parts.push("They could not be saved to this browser's storage.");
    } else if (n) {
      parts.push("Nothing new to import.");
    } else if (!bad) {
      parts.push("No expenses found in the file.");
    } else {
      parts.push("Nothing was imported.");
    }
    if (merged.skipped.length) {
      parts.push(plural(merged.skipped.length, "row") + " already in your list " +
        (merged.skipped.length === 1 ? "was" : "were") + " skipped.");
    }
    if (bad && parsed.rowCount) {
      parts.push(plural(bad, "row") + " had problems and " + (bad === 1 ? "was" : "were") + " skipped:");
    }

    showCsvStatus(parts.join(" "), parsed.errors, bad > 0 && merged.added.length === 0);
  }

  function readFileText(file) {
    if (file.text) return file.text();
    return new Promise(function (resolve, reject) {
      var reader = new FileReader();
      reader.onload = function () { resolve(reader.result); };
      reader.onerror = function () { reject(reader.error); };
      reader.readAsText(file);
    });
  }

  function onImportFile() {
    var file = importInput.files && importInput.files[0];
    importInput.value = ""; // allow choosing the same file again
    if (!file) return;
    if (file.size > MAX_IMPORT_BYTES) {
      showCsvStatus("That file is too large to import (limit 5 MB).", null, true);
      return;
    }
    readFileText(file).then(importCsvText, function () {
      showCsvStatus("Could not read that file.", null, true);
    });
  }

  // ---- Monthly summary ----------------------------------------------------

  function formatMonthLabel(month) {
    var p = month.split("-").map(Number);
    return new Date(p[0], p[1] - 1, 1).toLocaleDateString(undefined, {
      month: "long",
      year: "numeric"
    });
  }

  function formatShare(share) {
    if (share > 0 && share < 0.005) return "<1%";
    return Math.round(share * 100) + "%";
  }

  function plural(n, word) {
    return n + " " + word + (n === 1 ? "" : "s");
  }

  function makeEl(tag, className, text) {
    var e = document.createElement(tag);
    if (className) e.className = className;
    if (text != null) e.textContent = text;
    return e;
  }

  /** One line of text describing a row's budget, or "" when it has none. */
  function budgetText(row) {
    if (row.budget == null) return "";
    var budget = L.formatAmount(row.budget);
    if (row.status === B.STATUS.OVER) {
      return "Over budget by " + L.formatAmount(-row.remaining) +
        (row.budget > 0 ? " (" + row.percentLabel + " of " + budget + ")" : " (budget 0.00)");
    }
    var text = row.percentLabel + " of " + budget + " budget";
    if (row.status === B.STATUS.WARNING) text += " · " + L.formatAmount(row.remaining) + " left";
    return text;
  }

  /** Sentence for the alert list above the chart. */
  function alertText(row) {
    if (row.status === B.STATUS.OVER) {
      return row.category + " is over budget by " + L.formatAmount(-row.remaining) +
        (row.budget > 0 ? " (" + row.percentLabel + " of " + L.formatAmount(row.budget) + ")." : ".");
    }
    return row.category + " has used " + row.percentLabel + " of its " +
      L.formatAmount(row.budget) + " budget (" + L.formatAmount(row.remaining) + " left).";
  }

  var STATUS_WORD = { warning: "Warning", over: "Over budget" };

  /** Icon + label: status is never shown by colour alone. */
  function statusIcon(status) {
    var icon = makeEl("span", "status-icon status-icon-" + status, "!");
    icon.setAttribute("aria-hidden", "true");
    return icon;
  }

  function renderBarRow(row) {
    var amountText = L.formatAmount(row.total);
    var shareText = formatShare(row.share);
    var bText = budgetText(row);

    var cls = "bar-row is-" + row.status + (row.total === 0 ? " is-zero" : "");
    var el = makeEl("div", cls);
    el.setAttribute("role", "listitem");
    el.tabIndex = 0;
    el.setAttribute("aria-label",
      row.category + ": " + amountText + ", " + shareText + " of the month, " +
      plural(row.count, "expense") +
      (bText ? ". " + (STATUS_WORD[row.status] ? STATUS_WORD[row.status] + ": " : "") + bText : ""));

    el.appendChild(makeEl("span", "bar-label", row.category));

    var track = makeEl("span", "bar-track");
    if (row.total > 0) {
      var bar = makeEl("span", "bar");
      // One scale for bars and budget markers; keep tiny values visible.
      bar.style.width = "max(4px, " + (row.spentOfScale * 100).toFixed(2) + "%)";
      track.appendChild(bar);
    }
    if (row.budgetOfScale != null) {
      var marker = makeEl("span", "budget-marker");
      marker.style.left = "calc(" + (row.budgetOfScale * 100).toFixed(2) + "% - 1px)";
      marker.title = "Budget " + L.formatAmount(row.budget);
      track.appendChild(marker);
    }
    el.appendChild(track);

    el.appendChild(makeEl("span", "bar-value", amountText));

    if (bText) {
      var line = makeEl("span", "bar-budget");
      if (STATUS_WORD[row.status]) line.appendChild(statusIcon(row.status));
      line.appendChild(makeEl("span", null, bText));
      el.appendChild(line);
    }

    el.summaryRow = row;
    return el;
  }

  function usedText(row) {
    if (row.budget == null) return "—";
    return row.percentLabel + (STATUS_WORD[row.status] ? " · " + STATUS_WORD[row.status] : "");
  }

  function renderTableRow(row) {
    var tr = document.createElement("tr");
    if (row.status === B.STATUS.WARNING || row.status === B.STATUS.OVER) tr.className = "is-" + row.status;
    tr.appendChild(makeEl("td", null, row.category));
    tr.appendChild(makeEl("td", null, String(row.count)));
    tr.appendChild(makeEl("td", null, L.formatAmount(row.total)));
    tr.appendChild(makeEl("td", null, formatShare(row.share)));
    tr.appendChild(makeEl("td", null, row.budget == null ? "—" : L.formatAmount(row.budget)));
    tr.appendChild(makeEl("td", null, usedText(row)));
    return tr;
  }

  function renderAlerts(report) {
    var rows = report.over.concat(report.warnings);
    var items = rows.map(function (row) {
      var li = makeEl("li", "budget-alert is-" + row.status);
      li.appendChild(statusIcon(row.status));
      li.appendChild(makeEl("span", null, alertText(row)));
      return li;
    });
    budgetAlertListEl.replaceChildren.apply(budgetAlertListEl, items);
    budgetAlertsEl.hidden = items.length === 0;
  }

  function renderSummary() {
    var summary = L.summarizeMonth(expenses, selectedMonth);
    var report = B.budgetReport(summary, budgets);
    var hasData = summary.count > 0;

    if (monthInput.value !== selectedMonth) monthInput.value = selectedMonth;
    monthInput.removeAttribute("aria-invalid");

    monthLabelEl.textContent = formatMonthLabel(selectedMonth) + " total";
    monthTotalEl.textContent = L.formatAmount(summary.total);
    monthCountEl.textContent = "· " + plural(summary.count, "expense");

    hideTooltip();
    // With budgets set, the chart is still useful for an empty month:
    // it shows each budget marker with nothing spent yet.
    var showChart = hasData || report.hasBudgets;
    summaryEmptyEl.hidden = hasData;
    chartEl.hidden = !showChart;
    tableViewEl.hidden = !showChart;

    renderAlerts(report);
    barChartEl.replaceChildren.apply(barChartEl, report.categories.map(renderBarRow));

    var rows = report.categories.map(renderTableRow);
    var foot = document.createElement("tr");
    foot.className = "table-total";
    foot.appendChild(makeEl("td", null, "Total"));
    foot.appendChild(makeEl("td", null, String(summary.count)));
    foot.appendChild(makeEl("td", null, L.formatAmount(summary.total)));
    foot.appendChild(makeEl("td", null, summary.total > 0 ? "100%" : "0%"));
    foot.appendChild(makeEl("td", null, report.hasBudgets ? L.formatAmount(report.budgetTotal) : "—"));
    // "Used" compares only the categories that have a budget.
    foot.appendChild(makeEl("td", null, report.hasBudgets
      ? B.percentLabel(report.budgetedSpent, report.budgetTotal) + " of budgeted"
      : "—"));
    rows.push(foot);
    summaryTableEl.replaceChildren.apply(summaryTableEl, rows);
  }

  function setMonth(month) {
    if (!L.isValidMonth(month)) return;
    selectedMonth = month;
    renderSummary();
  }

  // ---- Chart tooltip (hover + keyboard focus) -----------------------------

  var activeRow = null;

  function showTooltip(rowEl) {
    var row = rowEl.summaryRow;
    if (!row) return;
    if (activeRow) activeRow.classList.remove("is-active");
    activeRow = rowEl;
    rowEl.classList.add("is-active");

    var lines = [
      makeEl("strong", null, row.category + " · " + L.formatAmount(row.total)),
      makeEl("span", null, formatShare(row.share) + " of the month · " + plural(row.count, "expense"))
    ];
    var bText = budgetText(row);
    if (bText) lines.push(makeEl("span", null, (STATUS_WORD[row.status] ? STATUS_WORD[row.status] + ": " : "") + bText));
    tooltipEl.replaceChildren.apply(tooltipEl, lines);
    tooltipEl.hidden = false;

    // Anchor just past the end of the bar, above the row; keep it inside the chart.
    var track = rowEl.querySelector(".bar-track");
    var bar = rowEl.querySelector(".bar");
    var left = track.offsetLeft + (bar ? bar.offsetWidth : 0);
    var maxLeft = chartEl.clientWidth - tooltipEl.offsetWidth - 8;
    tooltipEl.style.left = Math.max(0, Math.min(left, maxLeft)) + "px";
    tooltipEl.style.top = (rowEl.offsetTop + 2) + "px";
  }

  function hideTooltip() {
    if (activeRow) activeRow.classList.remove("is-active");
    activeRow = null;
    tooltipEl.hidden = true;
  }

  function rowFromEvent(e) {
    return e.target.closest ? e.target.closest(".bar-row") : null;
  }

  // ---- Form ---------------------------------------------------------------

  function showErrors(errors) {
    Object.keys(fields).forEach(function (name) {
      var msg = errors[name] || "";
      document.getElementById(name + "-error").textContent = msg;
      if (msg) {
        fields[name].setAttribute("aria-invalid", "true");
      } else {
        fields[name].removeAttribute("aria-invalid");
      }
    });
  }

  function readForm() {
    return {
      amount: amountInput.value,
      category: categoryInput.value,
      date: dateInput.value,
      note: noteInput.value
    };
  }

  function resetForm() {
    amountInput.value = "";
    noteInput.value = "";
    // Keep the chosen category and date: handy when entering several at once.
    amountInput.focus();
  }

  function onSubmit(event) {
    event.preventDefault();
    var input = readForm();
    var errors = L.validateExpense(input);
    showErrors(errors);

    var firstBad = Object.keys(fields).find(function (n) { return errors[n]; });
    if (firstBad) {
      fields[firstBad].focus();
      return;
    }

    var expense = L.createExpense(input, makeId(), Date.now());
    expenses = L.addExpense(expenses, expense);
    if (!saveExpenses(expenses)) {
      document.getElementById("note-error").textContent =
        "Added, but could not save to this browser's storage.";
    }
    render();
    resetForm();
  }

  // ---- Budget form --------------------------------------------------------

  function buildBudgetFields() {
    L.CATEGORIES.forEach(function (cat) {
      var id = "budget-" + cat.toLowerCase();
      var wrap = makeEl("div", "field budget-field");

      var label = makeEl("label", null, cat);
      label.htmlFor = id;

      var input = document.createElement("input");
      input.id = id;
      input.type = "number";
      input.inputMode = "decimal";
      input.min = "0";
      input.step = "0.01";
      input.placeholder = "No budget";

      var err = makeEl("p", "error");
      err.id = id + "-error";
      err.setAttribute("role", "alert");
      input.setAttribute("aria-describedby", err.id);

      input.addEventListener("input", function () {
        err.textContent = "";
        input.removeAttribute("aria-invalid");
        budgetSavedEl.textContent = "";
      });

      wrap.appendChild(label);
      wrap.appendChild(input);
      wrap.appendChild(err);
      budgetFieldsEl.appendChild(wrap);
      budgetInputs[cat] = input;
      budgetErrors[cat] = err;
    });
  }

  function fillBudgetFields() {
    L.CATEGORIES.forEach(function (cat) {
      var v = budgets[cat];
      budgetInputs[cat].value = v == null ? "" : (L.toCents(v) / 100).toFixed(2);
      budgetErrors[cat].textContent = "";
      budgetInputs[cat].removeAttribute("aria-invalid");
    });
  }

  function onBudgetSubmit(event) {
    event.preventDefault();
    var next = {};
    var firstBad = null;

    L.CATEGORIES.forEach(function (cat) {
      var input = budgetInputs[cat];
      // A number input with junk in it reports an empty value but bad validity.
      var raw = input.validity && input.validity.badInput ? "not a number" : input.value;
      var parsed = B.parseBudgetInput(raw);
      if (parsed.error) {
        budgetErrors[cat].textContent = parsed.error;
        input.setAttribute("aria-invalid", "true");
        if (!firstBad) firstBad = input;
      } else {
        budgetErrors[cat].textContent = "";
        input.removeAttribute("aria-invalid");
        next = B.setBudget(next, cat, parsed.value);
      }
    });

    if (firstBad) {
      budgetSavedEl.textContent = "";
      firstBad.focus();
      return;
    }

    budgets = next;
    budgetSavedEl.textContent = saveBudgets(budgets)
      ? "Budgets saved."
      : "Budgets applied, but could not be saved to this browser's storage.";
    fillBudgetFields();
    renderSummary();
  }

  // ---- Init ---------------------------------------------------------------

  L.CATEGORIES.forEach(function (cat) {
    var opt = document.createElement("option");
    opt.value = cat;
    opt.textContent = cat;
    categoryInput.appendChild(opt);
  });

  dateInput.value = L.toISODate(new Date());

  var expenses = loadExpenses();
  var budgets = loadBudgets();

  buildBudgetFields();
  fillBudgetFields();
  budgetForm.addEventListener("submit", onBudgetSubmit);

  form.addEventListener("submit", onSubmit);

  // Clear a field's error as soon as the user edits it.
  Object.keys(fields).forEach(function (name) {
    fields[name].addEventListener("input", function () {
      document.getElementById(name + "-error").textContent = "";
      fields[name].removeAttribute("aria-invalid");
    });
  });

  // Month picker. Browsers without <input type="month"> show a text box;
  // only a complete YYYY-MM value is accepted.
  function onMonthInput() {
    if (L.isValidMonth(monthInput.value)) {
      setMonth(monthInput.value);
    } else if (monthInput.value.length >= 7) {
      monthInput.setAttribute("aria-invalid", "true");
    }
  }
  monthInput.addEventListener("input", onMonthInput);
  monthInput.addEventListener("change", onMonthInput);
  monthInput.addEventListener("blur", function () {
    // Cleared or half-typed: put the selected month back.
    if (!L.isValidMonth(monthInput.value)) renderSummary();
  });
  prevMonthBtn.addEventListener("click", function () {
    setMonth(L.shiftMonth(selectedMonth, -1));
  });
  nextMonthBtn.addEventListener("click", function () {
    setMonth(L.shiftMonth(selectedMonth, 1));
  });

  barChartEl.addEventListener("mouseover", function (e) {
    var row = rowFromEvent(e);
    if (row && row !== activeRow) showTooltip(row);
  });
  barChartEl.addEventListener("mouseleave", hideTooltip);
  barChartEl.addEventListener("focusin", function (e) {
    var row = rowFromEvent(e);
    if (row) showTooltip(row);
  });
  barChartEl.addEventListener("focusout", hideTooltip);
  barChartEl.addEventListener("keydown", function (e) {
    if (e.key === "Escape") hideTooltip();
  });

  exportBtn.addEventListener("click", exportCsv);
  importInput.addEventListener("change", onImportFile);

  // Stay in sync if the tracker is open in another tab.
  window.addEventListener("storage", function (e) {
    if (e.key === STORAGE_KEY) {
      expenses = loadExpenses();
      render();
    } else if (e.key === BUDGET_KEY) {
      budgets = loadBudgets();
      fillBudgetFields();
      renderSummary();
    }
  });

  render();
})();

