/** Largest amount accepted anywhere (form, CSV, budgets): 999,999,999.99. */
var MAX_AMOUNT_CENTS = 99999999999;

/**
 * The one parser for amounts that people type (form, CSV cells, budget
 * boxes). Strict on purpose: plain decimals only, at most 2 decimal
 * places, optional thousands separators ("1,234.56"). No "1e3", "0x10",
 * "$12" or silent rounding.
 *
 * options.allowZero - accept 0 (budgets); otherwise it must be > 0.
 * options.label     - word used in messages (default "Amount").
 *
 * Returns { value } or { error }.
 */
function parseAmount(raw, options) {
  var opts = options || {};
  var label = opts.label || "Amount";
  var s = raw == null ? "" : String(raw).trim();
  if (s === "") return { error: label + " is missing." };

  var quoted = label + ' "' + s + '"';
  var negative = s.charAt(0) === "-";
  var body = negative ? s.slice(1) : s;
  if (/^\d{1,3}(,\d{3})+(\.\d*)?$/.test(body)) body = body.replace(/,/g, "");

  if (!/^(\d+(\.\d*)?|\.\d+)$/.test(body)) return { error: quoted + " is not a number." };
  if (/\.\d{3,}$/.test(body)) return { error: quoted + " has more than 2 decimal places." };

  // body is a plain decimal with <= 2 places, so shifting by e2 is exact.
  var cents = Math.round(Number(body + "e2"));
  if (negative && cents > 0) {
    return { error: opts.allowZero ? label + " can't be negative." : quoted + " must be greater than 0." };
  }
  if (cents === 0 && !opts.allowZero) return { error: quoted + " must be greater than 0." };
  if (cents > MAX_AMOUNT_CENTS) return { error: quoted + " is too large (max 999,999,999.99)." };
  return { value: cents / 100 };
}

/** Turn an errors object ({ field: message }) into one sentence list. */
function errorMessages(errors) {
  return Object.keys(errors || {}).map(function (k) { return errors[k]; }).join(" ");
}

