/*
 * Pure CSV reading and writing: no DOM, no files, no localStorage.
 *
 * Low level:  parseCSV(text) -> rows,  stringifyCSV(rows) -> text   (RFC 4180)
 * Expenses:   expensesToCSV(expenses) -> text
 *             csvToExpenses(text) -> { expenses, errors, rowCount }
 *
 * Loads in the browser (window.ExpenseCSV, after logic.js) or from Node.
 */
(function (root, factory) {
  "use strict";
  if (typeof module !== "undefined" && module.exports) {
    module.exports = factory(require("./logic.js"));
  } else {
    root.ExpenseCSV = factory(root.ExpenseLogic);
  }
})(typeof globalThis !== "undefined" ? globalThis : this, function (L) {
  "use strict";

