    }

    if (inQuotes) {
      var err = new Error("Line " + quoteLine + ": a quoted value is never closed.");
      err.line = quoteLine;
      throw err;
    }

    // Text that doesn't end in a newline still has a final record to flush.
    if (field !== "" || fields.length > 0 || wasQuoted) {
      endRecord();
    }

    return records;
  }

  /** Parse CSV text into an array of rows (arrays of strings). */
  function parseCSV(text) {
    return parseCSVRecords(text).map(function (r) { return r.fields; });
  }

  function needsQuotes(s) {
    return /[",\r\n]/.test(s) || /^\s|\s$/.test(s);
  }

  /** Turn one value into a CSV field, quoting only when needed. */
  function formatField(value) {
    var s = value == null ? "" : String(value);
    return needsQuotes(s) ? '"' + s.replace(/"/g, '""') + '"' : s;
  }

  /** Write rows (arrays of values) as CSV text with CRLF line endings. */
  function stringifyCSV(rows) {
    return (rows || []).map(function (row) {
      return row.map(formatField).join(",");
    }).join("\r\n") + ((rows || []).length ? "\r\n" : "");
  }

  // ---- Spreadsheet safety ------------------------------------------------
  // A cell starting with = + - @ can run as a formula when the CSV is opened
  // in Excel / Sheets. On export, such text gets a leading apostrophe; on
  // import, that apostrophe is removed again so a round trip is lossless.

  // Text that already starts with apostrophes before a formula character
  // gets one more, so it also survives the round trip unchanged.

  var NEEDS_PROTECTION = /^'*[=+\-@\t\r]/;
  var IS_PROTECTED = /^'+[=+\-@\t\r]/;

  function protectFormula(s) {
    return NEEDS_PROTECTION.test(s) ? "'" + s : s;
  }

  function unprotectFormula(s) {
    return IS_PROTECTED.test(s) ? s.slice(1) : s;
  }

  // ---- Expenses -> CSV ----------------------------------------------------

  /** Export expenses (newest first) as CSV text with a header row. */
  function expensesToCSV(expenses) {
    var rows = [HEADER.slice()];
    L.sortNewestFirst(expenses || []).forEach(function (e) {
      rows.push([
        e.date,
        e.category,
        (L.toCents(e.amount) / 100).toFixed(2),
        protectFormula(e.note || "")
      ]);
    });
    return stringifyCSV(rows);
  }

  // ---- CSV -> expenses ----------------------------------------------------
  // Amounts use logic.js's parseAmount, the same strict rules as the form.

  function matchCategory(raw) {
    var s = String(raw == null ? "" : raw).trim().toLowerCase();
    for (var i = 0; i < L.CATEGORIES.length; i++) {
      if (L.CATEGORIES[i].toLowerCase() === s) return L.CATEGORIES[i];
    }
    return null;
  }

  function isBlank(fields) {
    return fields.every(function (f) { return f.trim() === ""; });
  }

  function listCategories() {
    var c = L.CATEGORIES;
    return c.slice(0, -1).join(", ") + " or " + c[c.length - 1];
  }

  /**
   * Read expenses from CSV text.
   *
   * The first non-blank row must be a header naming the columns (any order,
   * any case): date, category, amount and optionally note. Blank rows are
   * skipped. Each bad row is reported and skipped; good rows are returned.
   *
   * Returns {
   *   expenses: [{ date, category, amount, note }],  // ready for createExpense
   *   errors:   [{ line, message }],                 // line is 1-based, or null
   *   rowCount: number of data rows read (good + bad)
   * }
   */
  function csvToExpenses(text) {
    var result = { expenses: [], errors: [], rowCount: 0 };

    var records;
    try {
      records = parseCSVRecords(text);
    } catch (e) {
      result.errors.push({ line: e.line == null ? null : e.line, message: e.message });
      return result;
    }

    records = records.filter(function (r) { return !isBlank(r.fields); });
    if (records.length === 0) {
      result.errors.push({ line: null, message: "The file is empty." });
      return result;
    }

    // Header row -> column positions.
    var headerRec = records[0];
    var col = {};
    headerRec.fields.forEach(function (name, idx) {
      var key = name.trim().toLowerCase();
      if (key === "notes") key = "note";
      if (HEADER.indexOf(key) !== -1 && !(key in col)) col[key] = idx;
    });
    var missing = REQUIRED.filter(function (k) { return !(k in col); });
    if (missing.length) {
      result.errors.push({
        line: headerRec.line,
        message: "Missing column" + (missing.length > 1 ? "s" : "") + ": " +
          missing.join(", ") + ". The first row must be a header like: " + HEADER.join(",")
      });
      return result;
    }

    function cell(fields, key) {
      return key in col && col[key] < fields.length ? fields[col[key]] : "";
    }

    records.slice(1).forEach(function (rec) {
      result.rowCount += 1;
      var problems = [];
      var f = rec.fields;

      var date = cell(f, "date").trim();
      if (!L.isValidDate(date)) {
        problems.push(date ? 'Date "' + date + '" is not a valid YYYY-MM-DD date.' : "Date is missing.");
      }

      var rawCat = cell(f, "category");
      var category = matchCategory(rawCat);
      if (!category) {
        problems.push(rawCat.trim()
          ? 'Unknown category "' + rawCat.trim() + '" (use ' + listCategories() + ")."
          : "Category is missing.");
      }

      var amount = parseAmount(cell(f, "amount"));
      if (amount.error) problems.push(amount.error);

      if (problems.length) {
        result.errors.push({ line: rec.line, message: problems.join(" ") });
        return;
      }

      var expense = {
        date: date,
        category: category,
        amount: amount.value,
        note: unprotectFormula(cell(f, "note").trim())
      };
      // Belt and braces: the app's own validation must agree.
      var errs = L.validateExpense(expense);
      var keys = Object.keys(errs);
      if (keys.length) {
        result.errors.push({ line: rec.line, message: keys.map(function (k) { return errs[k]; }).join(" ") });
        return;
      }
      result.expenses.push(expense);
    });

    return result;
  }

  return {
    HEADER: HEADER.slice(),
    parseCSV: parseCSV,
    parseCSVRecords: parseCSVRecords,
    stringifyCSV: stringifyCSV,
    formatField: formatField,
    parseAmount: parseAmount,
    expensesToCSV: expensesToCSV,
    csvToExpenses: csvToExpenses
  };
});

