"use strict";

const { describe, test } = require("node:test");
const assert = require("node:assert/strict");
const L = require("../logic.js");

function exp(id, amount, category, date, createdAt, note) {
  return L.createExpense({ amount, category, date, note }, id, createdAt);
}

describe("CATEGORIES", () => {
  test("are the five fixed categories, in order", () => {
    assert.deepEqual(L.CATEGORIES, ["Food", "Transport", "Bills", "Fun", "Other"]);
  });
});

describe("toCents", () => {
  test("converts numbers and numeric strings", () => {
    assert.equal(L.toCents(12.34), 1234);
    assert.equal(L.toCents("12.34"), 1234);
    assert.equal(L.toCents(" 5 "), 500);
    assert.equal(L.toCents(0.1 + 0.2), 30);
  });

  test("returns NaN for non-numbers", () => {
    for (const bad of ["", "   ", "abc", "12abc", null, undefined, NaN, Infinity, {}, []]) {
      assert.ok(Number.isNaN(L.toCents(bad)), `expected NaN for ${String(bad)}`);
    }
  });
});

describe("isValidDate", () => {
  test("accepts real YYYY-MM-DD dates, including leap days", () => {
    assert.ok(L.isValidDate("2026-11-22"));
    assert.ok(L.isValidDate("2024-02-29"));
  });

  test("rejects impossible or badly formatted dates", () => {
    for (const bad of ["2026-02-29", "2026-02-30", "2026-13-01", "2026-00-10", "2026-1-5",
      "22/11/2026", "", null, 20261122]) {
      assert.equal(L.isValidDate(bad), false, `expected invalid: ${bad}`);
    }
  });
});

describe("validateExpense", () => {
  const good = { amount: "12.50", category: "Food", date: "2026-11-22", note: "" };

  test("returns no errors for valid input", () => {
    assert.deepEqual(L.validateExpense(good), {});
    assert.deepEqual(L.validateExpense({ ...good, note: undefined }), {});
  });

  test("flags bad amounts", () => {
    for (const amount of ["", "abc", "0", "0.00", "-5", null, NaN]) {
      assert.ok(L.validateExpense({ ...good, amount }).amount, `amount ${amount} should fail`);
    }
  });

  test("flags unknown category and bad date", () => {
    const errs = L.validateExpense({ amount: "1", category: "food", date: "2026-02-30" });
    assert.deepEqual(Object.keys(errs).sort(), ["category", "date"]);
  });

  test("handles missing input", () => {
    assert.deepEqual(Object.keys(L.validateExpense()).sort(), ["amount", "category", "date"]);
  });
});

describe("createExpense", () => {
  test("normalises amount and trims note", () => {
    const e = L.createExpense({ amount: "12.5", category: "Food", date: "2026-11-20", note: "  lunch " }, 7, 100);
    assert.deepEqual(e, { id: "7", amount: 12.5, category: "Food", date: "2026-11-20", note: "lunch", createdAt: 100 });
  });

  test("rounds to whole cents", () => {
    assert.equal(L.createExpense({ amount: "1.005", category: "Fun", date: "2026-01-01" }, "x", 0).amount, 1.01);
  });

  test("throws on invalid input", () => {
    assert.throws(() => L.createExpense({ amount: "abc", category: "Food", date: "2026-01-01" }, "x", 0), /Invalid expense/);
  });
});

describe("calculateTotal", () => {
  test("is 0 for an empty or missing list", () => {
    assert.equal(L.calculateTotal([]), 0);
    assert.equal(L.calculateTotal(undefined), 0);
  });

  test("adds in cents, avoiding float drift", () => {
    assert.equal(L.calculateTotal([{ amount: 0.1 }, { amount: 0.2 }]), 0.3);
    assert.equal(L.calculateTotal([{ amount: 19.99 }, { amount: 0.01 }, { amount: 100 }]), 120);
  });

  test("ignores entries without a usable amount", () => {
    assert.equal(L.calculateTotal([{ amount: 5 }, { amount: "x" }, null, {}]), 5);
  });
});

describe("sortNewestFirst", () => {
  const a = exp("a", 1, "Food", "2026-11-20", 1);
  const b = exp("b", 1, "Food", "2026-11-22", 2);
  const c = exp("c", 1, "Food", "2026-11-20", 3);

  test("orders by date desc, then by createdAt desc", () => {
    assert.deepEqual(L.sortNewestFirst([a, b, c]).map((e) => e.id), ["b", "c", "a"]);
  });

  test("orders across months and years", () => {
    const old = exp("old", 1, "Food", "2025-12-31", 9);
    const neu = exp("new", 1, "Food", "2026-01-01", 0);
    assert.deepEqual(L.sortNewestFirst([old, neu]).map((e) => e.id), ["new", "old"]);
  });

  test("does not mutate its input", () => {
    const list = [a, b, c];
    L.sortNewestFirst(list);
    assert.deepEqual(list.map((e) => e.id), ["a", "b", "c"]);
  });

  test("handles an empty list", () => {
    assert.deepEqual(L.sortNewestFirst([]), []);
  });
});

describe("addExpense", () => {
  test("returns a new array", () => {
    const list = [];
    const out = L.addExpense(list, { id: "1" });
    assert.equal(out.length, 1);
    assert.equal(list.length, 0);
  });
});

describe("formatAmount", () => {
  test("formats with two decimals and thousands separators", () => {
    assert.equal(L.formatAmount(0), "0.00");
    assert.equal(L.formatAmount(5), "5.00");
    assert.equal(L.formatAmount(1234.5), "1,234.50");
    assert.equal(L.formatAmount(1234567.891), "1,234,567.89");
    assert.equal(L.formatAmount(-3.2), "-3.20");
  });

  test("treats unusable input as zero", () => {
    assert.equal(L.formatAmount("abc"), "0.00");
  });
});

describe("toISODate", () => {
  test("uses the local calendar date with zero padding", () => {
    assert.equal(L.toISODate(new Date(2026, 0, 5)), "2026-01-05");
    assert.equal(L.toISODate(new Date(2026, 11, 31, 23, 59)), "2026-12-31");
  });
});

describe("parseStoredExpenses", () => {
  test("returns [] for corrupt or non-array data", () => {
    assert.deepEqual(L.parseStoredExpenses("not json"), []);
    assert.deepEqual(L.parseStoredExpenses(""), []);
    assert.deepEqual(L.parseStoredExpenses('{"a":1}'), []);
    assert.deepEqual(L.parseStoredExpenses("null"), []);
  });

  test("keeps valid entries and drops invalid ones", () => {
    const good = exp("g", 3, "Bills", "2026-11-01", 5, "rent");
    const out = L.parseStoredExpenses(JSON.stringify([good, { id: "bad", amount: -1 }, null, 7, { amount: 1, category: "Food", date: "2026-01-01" }]));
    assert.deepEqual(out, [good]);
  });
});

describe("month helpers", () => {
  test("isValidMonth", () => {
    assert.ok(L.isValidMonth("2026-11"));
    for (const bad of ["2026-13", "2026-00", "2026-1", "", null, "2026-11-01"]) {
      assert.equal(L.isValidMonth(bad), false, String(bad));
    }
  });

  test("monthOf", () => {
    assert.equal(L.monthOf("2026-11-22"), "2026-11");
  });

  test("shiftMonth crosses year boundaries", () => {
    assert.equal(L.shiftMonth("2026-01", -1), "2025-12");
    assert.equal(L.shiftMonth("2026-12", 1), "2027-01");
    assert.equal(L.shiftMonth("2026-05", -17), "2024-12");
    assert.equal(L.shiftMonth("2026-05", 24), "2028-05");
    assert.equal(L.shiftMonth("2026-05", 0), "2026-05");
  });

  test("filterByMonth matches year and month", () => {
    const list = [
      exp("a", 1, "Food", "2026-11-01", 0),
      exp("b", 1, "Food", "2025-11-15", 0),
      exp("c", 1, "Food", "2026-10-31", 0),
      exp("d", 1, "Food", "2026-11-30", 0)
    ];
    assert.deepEqual(L.filterByMonth(list, "2026-11").map((e) => e.id), ["a", "d"]);
    assert.deepEqual(L.filterByMonth([], "2026-11"), []);
  });
});

describe("summarizeMonth", () => {
  const list = [
    exp("a", 12.5, "Food", "2026-11-20", 1),
    exp("b", 0.1, "Food", "2026-11-02", 2),
    exp("c", 0.2, "Bills", "2026-11-30", 3),
    exp("d", 99, "Fun", "2026-10-31", 4)
  ];

  test("totals per category for the month, in fixed order", () => {
    const s = L.summarizeMonth(list, "2026-11");
    assert.equal(s.month, "2026-11");
    assert.equal(s.count, 3);
    assert.equal(s.total, 12.8);
    assert.deepEqual(s.categories.map((r) => r.category), L.CATEGORIES);
    assert.deepEqual(s.categories.map((r) => r.total), [12.6, 0, 0.2, 0, 0]);
    assert.deepEqual(s.categories.map((r) => r.count), [2, 0, 1, 0, 0]);
    assert.equal(s.categories[0].ofMax, 1);
    assert.ok(Math.abs(s.categories[0].share - 12.6 / 12.8) < 1e-12);
  });

  test("an empty month has zeros everywhere (no divide by zero)", () => {
    const s = L.summarizeMonth(list, "2020-01");
    assert.equal(s.count, 0);
    assert.equal(s.total, 0);
    for (const r of s.categories) {
      assert.deepEqual([r.total, r.count, r.share, r.ofMax], [0, 0, 0, 0]);
    }
  });
});

describe("mergeExpenses", () => {
  const coffee = (id) => exp(id, 3, "Food", "2026-05-01", 0, "coffee");

  test("adds new expenses and keeps the existing ones", () => {
    const existing = [coffee("1")];
    const incoming = [exp("2", 10, "Fun", "2026-05-02", 0)];
    const r = L.mergeExpenses(existing, incoming);
    assert.deepEqual(r.expenses.map((e) => e.id), ["1", "2"]);
    assert.equal(r.added.length, 1);
    assert.equal(r.skipped.length, 0);
    assert.equal(existing.length, 1, "input not mutated");
  });

  test("re-importing the same data adds nothing", () => {
    const existing = [coffee("1"), exp("2", 10, "Fun", "2026-05-02", 0)];
    const again = [coffee("x"), exp("y", 10, "Fun", "2026-05-02", 0)];
    const r = L.mergeExpenses(existing, again);
    assert.equal(r.added.length, 0);
    assert.equal(r.skipped.length, 2);
    assert.equal(r.expenses.length, 2);
  });

  test("counts copies, so genuine repeats are kept", () => {
    const r = L.mergeExpenses([coffee("1")], [coffee("a"), coffee("b")]);
    assert.equal(r.skipped.length, 1);
    assert.equal(r.added.length, 1);
    assert.equal(r.expenses.length, 2);
  });

  test("treats 3 and 3.00 as the same amount, but a different note as different", () => {
    const r = L.mergeExpenses([coffee("1")], [
      { id: "a", amount: 3.0, category: "Food", date: "2026-05-01", note: "coffee" },
      { id: "b", amount: 3, category: "Food", date: "2026-05-01", note: "tea" }
    ]);
    assert.deepEqual(r.added.map((e) => e.id), ["b"]);
  });

  test("handles empty lists", () => {
    assert.deepEqual(L.mergeExpenses([], []).expenses, []);
    assert.equal(L.mergeExpenses(undefined, [coffee("1")]).added.length, 1);
  });
});

