describe("parseAmount (shared by form, CSV and budgets)", () => {
  test("accepts ordinary amounts", () => {
    assert.deepEqual(L.parseAmount("12"), { value: 12 });
    assert.deepEqual(L.parseAmount("12.5"), { value: 12.5 });
    assert.deepEqual(L.parseAmount(" 12.50 "), { value: 12.5 });
    assert.deepEqual(L.parseAmount("12."), { value: 12 });
    assert.deepEqual(L.parseAmount(".5"), { value: 0.5 });
    assert.deepEqual(L.parseAmount("0.10"), { value: 0.1 });
    assert.deepEqual(L.parseAmount("1,234.56"), { value: 1234.56 });
    assert.deepEqual(L.parseAmount("1,234,567"), { value: 1234567 });
    assert.deepEqual(L.parseAmount("999999999.99"), { value: 999999999.99 });
    assert.deepEqual(L.parseAmount(42), { value: 42 });
  });

  test("rejects bad amounts with a reason", () => {
    const cases = {
      "": /missing/,
      "   ": /missing/,
      abc: /not a number/,
      "12abc": /not a number/,
      "$12": /not a number/,
      "1.2.3": /not a number/,
      "12,34": /not a number/,
      "1e3": /not a number/,
      "0x10": /not a number/,
      "Infinity": /not a number/,
      "0": /greater than 0/,
      "0.00": /greater than 0/,
      "-5": /greater than 0/,
      "-0.5": /greater than 0/,
      "-1,234.50": /greater than 0/,
      "12.345": /2 decimal places/,
      "1.005": /2 decimal places/,
      "1000000000": /too large/,
      "99999999999999999999": /too large/
    };
    for (const [input, reason] of Object.entries(cases)) {
      const r = L.parseAmount(input);
      assert.equal(r.value, undefined, `"${input}" should be rejected`);
      assert.match(r.error, reason, `"${input}"`);
    }
    assert.match(L.parseAmount(null).error, /missing/);
  });

  test("allowZero and label options", () => {
    assert.deepEqual(L.parseAmount("0", { allowZero: true }), { value: 0 });
    assert.deepEqual(L.parseAmount("-0", { allowZero: true }), { value: 0 });
    assert.equal(L.parseAmount("-5", { allowZero: true, label: "Budget" }).error, "Budget can't be negative.");
    assert.equal(L.parseAmount("x", { label: "Budget" }).error, 'Budget "x" is not a number.');
  });
});

describe("errorMessages", () => {
  test("joins messages in field order", () => {
    assert.equal(L.errorMessages({ amount: "A.", date: "B." }), "A. B.");
    assert.equal(L.errorMessages({}), "");
    assert.equal(L.errorMessages(undefined), "");
  });
});

