describe("readStoredExpenses (reports what it couldn't keep)", () => {
  const good = exp("g", 3, "Bills", "2026-11-01", 5, "rent");

  test("missing storage is empty, not a problem", () => {
    assert.deepEqual(L.readStoredExpenses(null), { expenses: [], dropped: 0, unreadable: false });
    assert.deepEqual(L.readStoredExpenses(""), { expenses: [], dropped: 0, unreadable: false });
    assert.deepEqual(L.readStoredExpenses("[]"), { expenses: [], dropped: 0, unreadable: false });
  });

  test("clean data: nothing dropped", () => {
    assert.deepEqual(L.readStoredExpenses(JSON.stringify([good])), { expenses: [good], dropped: 0, unreadable: false });
  });

  test("counts dropped entries, e.g. a category from another version", () => {
    const future = { id: "h", amount: 5, category: "Health", date: "2026-11-02", note: "", createdAt: 1 };
    const r = L.readStoredExpenses(JSON.stringify([good, future, null]));
    assert.deepEqual(r.expenses, [good]);
    assert.equal(r.dropped, 2);
    assert.equal(r.unreadable, false);
  });

  test("flags text that isn't a JSON array", () => {
    for (const text of ["{bad json", '{"a":1}', "null", "42"]) {
      assert.deepEqual(L.readStoredExpenses(text), { expenses: [], dropped: 0, unreadable: true }, text);
    }
  });
});

