test("rejects negatives, non-numbers, extra decimals and huge values", () => {
  assert.equal(B.parseBudgetInput("-5").error, "Budget can't be negative.");
  for (const bad of ["abc", "12abc", "0x10", "1e3"]) {
    assert.match(B.parseBudgetInput(bad).error, /not a number/, bad);
  }
  // Previously "0.004" silently became a budget of 0 ("spend nothing").
  assert.match(B.parseBudgetInput("0.004").error, /2 decimal places/);
  assert.match(B.parseBudgetInput("10.005").error, /2 decimal places/);
  assert.match(B.parseBudgetInput("1000000000").error, /too large/);
});

