  assert.deepEqual(B.readStoredBudgets(null), { budgets: {}, dropped: 0, unreadable: false });
  assert.deepEqual(B.readStoredBudgets('{"Food":10}'), { budgets: { Food: 10 }, dropped: 0, unreadable: false });
