/*
 * Browser glue: DOM, events and localStorage.
 * All calculations live in the pure modules:
 *   logic.js  (window.ExpenseLogic)  expenses, totals, months, amounts
 *   csv.js    (window.ExpenseCSV)    CSV reading and writing
 *   budget.js (window.ExpenseBudget) budget rules and status
 */
(function () {
  "use strict";

  // ---- Dependencies & constants -------------------------------------------

  var L = window.ExpenseLogic;
  var C = window.ExpenseCSV;
  var B = window.ExpenseBudget;

  var EXPENSES_KEY = "expense-tracker.expenses";
  var BUDGETS_KEY = "expense-tracker.budgets";
  var MAX_IMPORT_BYTES = 5 * 1024 * 1024;
  var MAX_ERRORS_SHOWN = 10;
  var STATUS_WORD = { warning: "Warning", over: "Over budget" };

  // ---- DOM ----------------------------------------------------------------

  function $(id) { return document.getElementById(id); }

  var form = $("expense-form");
  var fields = { amount: $("amount"), category: $("category"), date: $("date"), note: $("note") };
  var listEl = $("expense-list");
  var totalEl = $("total");
  var countEl = $("count");
  var emptyEl = $("empty");

  var monthInput = $("month");
  var prevMonthBtn = $("prev-month");
  var nextMonthBtn = $("next-month");
  var monthLabelEl = $("month-label");
  var monthTotalEl = $("month-total");
  var monthCountEl = $("month-count");
  var summaryEmptyEl = $("summary-empty");
  var chartEl = $("chart");
  var barChartEl = $("bar-chart");
  var tooltipEl = $("chart-tooltip");
  var tableViewEl = $("table-view");
  var summaryTableEl = $("summary-table");
  var budgetAlertsEl = $("budget-alerts");
  var budgetAlertListEl = $("budget-alert-list");

  var budgetForm = $("budget-form");
  var budgetFieldsEl = $("budget-fields");
  var budgetSavedEl = $("budget-saved");
  var budgetInputs = {};   // category -> <input>
  var budgetErrors = {};   // category -> error <p>

  var importInput = $("import-file");
  var exportBtn = $("export-btn");
  var noticeEl = $("notice");
  var noticeTextEl = $("notice-text");
  var noticeErrorsEl = $("notice-errors");

  // ---- State --------------------------------------------------------------

  var expenses = [];
  var budgets = {};
  var selectedMonth = L.monthOf(L.toISODate(new Date()));
  var activeRow = null;       // bar row showing the tooltip
  var budgetDirty = false;    // budget form has unsaved edits
  // Set when stored data couldn't be fully read AND couldn't be backed up:
  // then we never write that key, so the original is not overwritten.
  var locked = {};

  // ---- Small helpers ------------------------------------------------------

  function makeEl(tag, className, text) {
    var e = document.createElement(tag);
    if (className) e.className = className;
    if (text != null) e.textContent = text;
    return e;
  }

  /** Replace an element's children (safe for any number of nodes). */
  function setChildren(parent, nodes) {
    var frag = document.createDocumentFragment();
    nodes.forEach(function (n) { frag.appendChild(n); });
    parent.replaceChildren(frag);
  }

  function plural(n, word) {
    return n + " " + word + (n === 1 ? "" : "s");
  }

  function formatShare(share) {
    if (share > 0 && share < 0.005) return "<1%";
    return Math.round(share * 100) + "%";
  }

  function formatDisplayDate(iso) {
    var p = iso.split("-").map(Number);
    return new Date(p[0], p[1] - 1, p[2]).toLocaleDateString(undefined, {
      year: "numeric", month: "short", day: "numeric"
    });
  }

  function formatMonthLabel(month) {
    var p = month.split("-").map(Number);
    return new Date(p[0], p[1] - 1, 1).toLocaleDateString(undefined, {
      month: "long", year: "numeric"
    });
  }

  var idCounter = 0;
  function makeId() {
    idCounter += 1;
    return Date.now().toString(36) + "-" + idCounter.toString(36) + "-" +
      Math.random().toString(36).slice(2, 8);
  }

  // ---- Notice (one place for import/export results and storage problems) --

  function showNotice(message, errors, isError) {
    noticeTextEl.textContent = message;
    var items = (errors || []).slice(0, MAX_ERRORS_SHOWN).map(function (err) {
      return makeEl("li", null, (err.line ? "Line " + err.line + ": " : "") + err.message);
    });
    if (errors && errors.length > MAX_ERRORS_SHOWN) {
      items.push(makeEl("li", null, "…and " + (errors.length - MAX_ERRORS_SHOWN) + " more."));
    }
    setChildren(noticeErrorsEl, items);
    noticeEl.classList.toggle("is-error", !!isError);
    noticeEl.hidden = false;
  }

  // ---- Storage ------------------------------------------------------------

  function storageGet(key) {
    try {
      return { ok: true, text: localStorage.getItem(key) };
    } catch (e) {
      return { ok: false, text: null }; // e.g. storage blocked by the browser
    }
  }

  function storageSet(key, value) {
    if (locked[key]) return false;
    try {
      localStorage.setItem(key, value);
      return true;
    } catch (e) {
      return false;
    }
  }

  /**
   * Keep a copy of `text` under "<key>.backup-<time>", unless an identical
   * backup already exists. Returns the backup key, or null if it failed.
   */
  function backup(key, text) {
    try {
      var prefix = key + ".backup-";
      for (var i = 0; i < localStorage.length; i++) {
        var k = localStorage.key(i);
        if (k && k.indexOf(prefix) === 0 && localStorage.getItem(k) === text) return k;
      }
      var name = prefix + new Date().toISOString();
      localStorage.setItem(name, text);
      return name;
    } catch (e) {
      return null;
    }
  }

  /**
   * Load one key through a reader returning { value, dropped, unreadable }.
   * If anything couldn't be kept, the original text is backed up BEFORE we
   * could ever save over it; if even that fails, the key is locked.
   */
  function load(key, what, read) {
    var raw = storageGet(key);
    if (!raw.ok) {
      showNotice("Browser storage isn't available, so " + what + " won't be kept after you close the page.", null, true);
      return read(null).value;
    }
    var r = read(raw.text);
    if (!r.dropped && !r.unreadable) return r.value;

    var problem = r.unreadable
      ? "Saved " + what + " couldn't be read (the data is damaged)."
      : plural(r.dropped, "saved entry") + " in " + what + " couldn't be read and " +
        (r.dropped === 1 ? "is" : "are") + " not shown.";
    var copy = backup(key, raw.text);
    if (copy) {
      locked[key] = false;
      showNotice(problem + " The original data was kept in browser storage as \u201c" + copy + "\u201d.", null, true);
    } else {
      locked[key] = true;
      showNotice(problem + " A backup couldn't be made, so changes to " + what +
        " won't be saved in this session, to avoid overwriting the original.", null, true);
    }
    return r.value;
  }

  function loadExpenses() {
    return load(EXPENSES_KEY, "expenses", function (text) {
      var r = L.readStoredExpenses(text);
      return { value: r.expenses, dropped: r.dropped, unreadable: r.unreadable };
    });
  }

  function loadBudgets() {
    return load(BUDGETS_KEY, "budgets", function (text) {
      var r = B.readStoredBudgets(text);
      return { value: r.budgets, dropped: r.dropped, unreadable: r.unreadable };
    });
  }

  function saveExpenses() {
    return storageSet(EXPENSES_KEY, JSON.stringify(expenses));
  }

  function saveBudgets() {
    return storageSet(BUDGETS_KEY, JSON.stringify(budgets));
  }

  // ---- Expense list -------------------------------------------------------

  function renderExpense(expense) {
    var li = makeEl("li", "expense");

    var main = makeEl("div", "expense-main");
    main.appendChild(makeEl("span", "badge badge-" + expense.category.toLowerCase(), expense.category));
    // textContent everywhere: user text is never parsed as HTML.
    if (expense.note) main.appendChild(makeEl("span", "expense-note", expense.note));

    var meta = makeEl("time", "expense-meta", formatDisplayDate(expense.date));
    meta.dateTime = expense.date;

    li.appendChild(main);
    li.appendChild(makeEl("span", "expense-amount", L.formatAmount(expense.amount)));
    li.appendChild(meta);
    return li;
  }

  function render() {
    var sorted = L.sortNewestFirst(expenses);
    setChildren(listEl, sorted.map(renderExpense));
    totalEl.textContent = L.formatAmount(L.calculateTotal(expenses));
    countEl.textContent = sorted.length ? "(" + sorted.length + ")" : "";
    emptyEl.hidden = sorted.length > 0;
    exportBtn.disabled = sorted.length === 0;
    renderSummary();
  }

  // ---- Monthly summary & budgets ------------------------------------------

  /** "85% of 100.00" - shared by every budget message. */
  function ofBudget(row) {
    return row.percentLabel + " of " + L.formatAmount(row.budget);
  }

  /** Short line under a bar, or "" when the category has no budget. */
  function budgetText(row) {
    if (row.budget == null) return "";
    if (row.status === B.STATUS.OVER) {
      return "Over budget by " + L.formatAmount(-row.remaining) + " (" + ofBudget(row) + ")";
    }
    return ofBudget(row) + " budget" +
      (row.status === B.STATUS.WARNING ? " · " + L.formatAmount(row.remaining) + " left" : "");
  }

  /** Sentence for the alert list above the chart (warning/over rows only). */
  function alertText(row) {
    if (row.status === B.STATUS.OVER) {
      return row.category + " is over budget by " + L.formatAmount(-row.remaining) + " (" + ofBudget(row) + ").";
    }
    return row.category + " has used " + ofBudget(row) + " budget (" + L.formatAmount(row.remaining) + " left).";
  }

  /** "Warning: " / "Over budget: " / "" */
  function statusPrefix(row) {
    return STATUS_WORD[row.status] ? STATUS_WORD[row.status] + ": " : "";
  }

  /** Icon + label: status is never shown by colour alone. */
  function statusIcon(status) {
    var icon = makeEl("span", "status-icon status-icon-" + status, "!");
    icon.setAttribute("aria-hidden", "true");
    return icon;
  }

  function renderBarRow(row) {
    var amountText = L.formatAmount(row.total);
    var bText = budgetText(row);

    var el = makeEl("div", "bar-row is-" + row.status + (row.total === 0 ? " is-zero" : ""));
    el.setAttribute("role", "listitem");
    el.tabIndex = 0;
    el.setAttribute("aria-label",
      row.category + ": " + amountText + ", " + formatShare(row.share) + " of the month, " +
      plural(row.count, "expense") + (bText ? ". " + statusPrefix(row) + bText : ""));

    el.appendChild(makeEl("span", "bar-label", row.category));

    var track = makeEl("span", "bar-track");
    if (row.total > 0) {
      var bar = makeEl("span", "bar");
      // One scale for bars and budget markers; keep tiny values visible.
      bar.style.width = "max(4px, " + (row.spentOfScale * 100).toFixed(2) + "%)";
      track.appendChild(bar);
    }
    if (row.budgetOfScale != null) {
      var marker = makeEl("span", "budget-marker");
      marker.style.left = "calc(" + (row.budgetOfScale * 100).toFixed(2) + "% - 1px)";
      marker.title = "Budget " + L.formatAmount(row.budget);
      track.appendChild(marker);
    }
    el.appendChild(track);
    el.appendChild(makeEl("span", "bar-value", amountText));

    if (bText) {
      var line = makeEl("span", "bar-budget");
      if (STATUS_WORD[row.status]) line.appendChild(statusIcon(row.status));
      line.appendChild(makeEl("span", null, bText));
      el.appendChild(line);
    }

    el.summaryRow = row;
    return el;
  }

  function tableRow(cells, className) {
    var tr = makeEl("tr", className || null);
    cells.forEach(function (text) { tr.appendChild(makeEl("td", null, text)); });
    return tr;
  }

  function renderTableRow(row) {
    var flagged = row.status === B.STATUS.WARNING || row.status === B.STATUS.OVER;
    return tableRow([
      row.category,
      String(row.count),
      L.formatAmount(row.total),
      formatShare(row.share),
      row.budget == null ? "—" : L.formatAmount(row.budget),
      row.budget == null ? "—" : row.percentLabel + (STATUS_WORD[row.status] ? " · " + STATUS_WORD[row.status] : "")
    ], flagged ? "is-" + row.status : null);
  }

  function renderAlerts(report) {
    var items = report.over.concat(report.warnings).map(function (row) {
      var li = makeEl("li", "budget-alert is-" + row.status);
      li.appendChild(statusIcon(row.status));
      li.appendChild(makeEl("span", null, alertText(row)));
      return li;
    });
    setChildren(budgetAlertListEl, items);
    budgetAlertsEl.hidden = items.length === 0;
  }

  function renderSummary() {
    var summary = L.summarizeMonth(expenses, selectedMonth);
    var report = B.budgetReport(summary, budgets);
    var hasData = summary.count > 0;

    if (monthInput.value !== selectedMonth) monthInput.value = selectedMonth;
    monthInput.removeAttribute("aria-invalid");
    prevMonthBtn.disabled = !L.shiftMonth(selectedMonth, -1);
    nextMonthBtn.disabled = !L.shiftMonth(selectedMonth, 1);

    monthLabelEl.textContent = formatMonthLabel(selectedMonth) + " total";
    monthTotalEl.textContent = L.formatAmount(summary.total);
    monthCountEl.textContent = "· " + plural(summary.count, "expense");

    hideTooltip();
    // With budgets set, the chart is still useful for an empty month:
    // it shows each budget marker with nothing spent yet.
    var showChart = hasData || report.hasBudgets;
    summaryEmptyEl.hidden = hasData;
    chartEl.hidden = !showChart;
    tableViewEl.hidden = !showChart;

    renderAlerts(report);
    setChildren(barChartEl, report.categories.map(renderBarRow));

    var rows = report.categories.map(renderTableRow);
    rows.push(tableRow([
      "Total",
      String(summary.count),
      L.formatAmount(summary.total),
      summary.total > 0 ? "100%" : "0%",
      report.hasBudgets ? L.formatAmount(report.budgetTotal) : "—",
      // "Used" compares only the categories that have a budget.
      report.hasBudgets ? report.budgetedLabel + " of budgeted" : "—"
    ], "table-total"));
    setChildren(summaryTableEl, rows);
  }

  function setMonth(month) {
    if (!L.isValidMonth(month)) return;
    if (month === selectedMonth) {
      monthInput.removeAttribute("aria-invalid");
      return; // nothing to redraw ("input" and "change" both fire on a pick)
    }
    selectedMonth = month;
    renderSummary();
  }

  // ---- Chart tooltip (hover + keyboard focus) -----------------------------

  function showTooltip(rowEl) {
    var row = rowEl.summaryRow;
    if (!row) return;
    if (activeRow) activeRow.classList.remove("is-active");
    activeRow = rowEl;
    rowEl.classList.add("is-active");

    var lines = [
      makeEl("strong", null, row.category + " · " + L.formatAmount(row.total)),
      makeEl("span", null, formatShare(row.share) + " of the month · " + plural(row.count, "expense"))
    ];
    var bText = budgetText(row);
    if (bText) lines.push(makeEl("span", null, statusPrefix(row) + bText));
    setChildren(tooltipEl, lines);
    tooltipEl.hidden = false;

    // Anchor just past the end of the bar, above the row; keep it inside the chart.
    var track = rowEl.querySelector(".bar-track");
    var bar = rowEl.querySelector(".bar");
    var left = track.offsetLeft + (bar ? bar.offsetWidth : 0);
    var maxLeft = chartEl.clientWidth - tooltipEl.offsetWidth - 8;
    tooltipEl.style.left = Math.max(0, Math.min(left, maxLeft)) + "px";
    tooltipEl.style.top = (rowEl.offsetTop + 2) + "px";
  }

  function hideTooltip() {
    if (activeRow) activeRow.classList.remove("is-active");
    activeRow = null;
    tooltipEl.hidden = true;
  }

  function rowFromEvent(e) {
    return e.target.closest ? e.target.closest(".bar-row") : null;
  }

  // ---- Add-expense form ---------------------------------------------------

  function setFieldError(input, errorEl, message) {
    errorEl.textContent = message || "";
    if (message) input.setAttribute("aria-invalid", "true");
    else input.removeAttribute("aria-invalid");
  }

  function onSubmit(event) {
    event.preventDefault();
    var input = {
      amount: fields.amount.value,
      category: fields.category.value,
      date: fields.date.value,
      note: fields.note.value
    };
    var errors = L.validateExpense(input);
    // A number box holding junk reports an empty value; say what's wrong.
    if (fields.amount.validity && fields.amount.validity.badInput) errors.amount = "Amount is not a number.";

    Object.keys(fields).forEach(function (name) {
      setFieldError(fields[name], $(name + "-error"), errors[name]);
    });
    var firstBad = Object.keys(fields).find(function (n) { return errors[n]; });
    if (firstBad) {
      fields[firstBad].focus();
      return;
    }

    expenses = L.addExpense(expenses, L.createExpense(input, makeId(), Date.now()));
    if (!saveExpenses()) {
      showNotice("Expense added, but it could not be saved to this browser's storage.", null, true);
    }
    render();

    fields.amount.value = "";
    fields.note.value = "";
    // Keep the chosen category and date: handy when entering several at once.
    fields.amount.focus();
  }

  // ---- Budget form --------------------------------------------------------

  function buildBudgetFields() {
    L.CATEGORIES.forEach(function (cat) {
      var id = "budget-" + cat.toLowerCase();
      var wrap = makeEl("div", "field budget-field");

      var label = makeEl("label", null, cat);
      label.htmlFor = id;

      var input = document.createElement("input");
      input.id = id;
      input.type = "number";
      input.inputMode = "decimal";
      input.min = "0";
      input.step = "0.01";
      input.placeholder = "No budget";

      var err = makeEl("p", "error");
      err.id = id + "-error";
      err.setAttribute("role", "alert");
      input.setAttribute("aria-describedby", err.id);

      input.addEventListener("input", function () {
        setFieldError(input, err, "");
        budgetSavedEl.textContent = "";
        budgetDirty = true;
      });

      wrap.appendChild(label);
      wrap.appendChild(input);
      wrap.appendChild(err);
      budgetFieldsEl.appendChild(wrap);
      budgetInputs[cat] = input;
      budgetErrors[cat] = err;
    });
  }

  function fillBudgetFields() {
    L.CATEGORIES.forEach(function (cat) {
      var v = budgets[cat];
      budgetInputs[cat].value = v == null ? "" : v.toFixed(2);
      setFieldError(budgetInputs[cat], budgetErrors[cat], "");
    });
    budgetDirty = false;
  }

  function onBudgetSubmit(event) {
    event.preventDefault();
    var next = {};
    var firstBad = null;

    L.CATEGORIES.forEach(function (cat) {
      var input = budgetInputs[cat];
      var parsed = input.validity && input.validity.badInput
        ? { error: "Budget is not a number." } // number box holding junk
        : B.parseBudgetInput(input.value);
      setFieldError(input, budgetErrors[cat], parsed.error);
      if (parsed.error) {
        if (!firstBad) firstBad = input;
      } else {
        next = B.setBudget(next, cat, parsed.value);
      }
    });

    if (firstBad) {
      budgetSavedEl.textContent = "";
      firstBad.focus();
      return;
    }

    budgets = next;
    var saved = saveBudgets();
    fillBudgetFields();
    budgetSavedEl.textContent = saved
      ? "Budgets saved."
      : "Budgets applied, but could not be saved to this browser's storage.";
    renderSummary();
  }

  // ---- CSV import / export ------------------------------------------------

  function exportCsv() {
    if (!expenses.length) return;
    var filename = "expenses-" + L.toISODate(new Date()) + ".csv";
    // The BOM makes Excel read non-ASCII notes as UTF-8.
    var blob = new Blob(["\uFEFF" + C.expensesToCSV(expenses)], { type: "text/csv;charset=utf-8" });
    var url = URL.createObjectURL(blob);
    var a = makeEl("a");
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    a.remove();
    setTimeout(function () { URL.revokeObjectURL(url); }, 1000);
    showNotice("Exported " + plural(expenses.length, "expense") + " to " + filename + ".");
  }

  /** Apply CSV text to the list and report the outcome in the notice. */
  function importCsvText(text) {
    var parsed = C.csvToExpenses(text);
    var base = Date.now();
    var n = parsed.expenses.length;
    // Earlier rows count as newer, matching the newest-first export order.
    var incoming = parsed.expenses.map(function (input, i) {
      return L.createExpense(input, makeId(), base + (n - i));
    });

    var merged = L.mergeExpenses(expenses, incoming);
    var bad = parsed.errors.length;
    var parts = [];

    if (merged.added.length) {
      expenses = merged.expenses;
      var saved = saveExpenses();
      render();
      parts.push("Imported " + plural(merged.added.length, "expense") + ".");
      if (!saved) parts.push("They could not be saved to this browser's storage, so they'll be gone when you close the page.");
    } else if (n) {
      parts.push("Nothing new to import.");
    } else if (!bad) {
      parts.push("No expenses found in the file.");
    } else {
      parts.push("Nothing was imported.");
    }
    if (merged.skipped.length) {
      parts.push(plural(merged.skipped.length, "row") + " already in your list " +
        (merged.skipped.length === 1 ? "was" : "were") + " skipped.");
    }
    if (bad && parsed.rowCount) {
      parts.push(plural(bad, "row") + " had problems and " + (bad === 1 ? "was" : "were") + " skipped:");
    }

    showNotice(parts.join(" "), parsed.errors, bad > 0 && merged.added.length === 0);
  }

  function readFileText(file) {
    if (file.text) return file.text();
    return new Promise(function (resolve, reject) {
      var reader = new FileReader();
      reader.onload = function () { resolve(reader.result); };
      reader.onerror = function () { reject(reader.error); };
      reader.readAsText(file);
    });
  }

  function onImportFile() {
    var file = importInput.files && importInput.files[0];
    importInput.value = ""; // allow choosing the same file again
    if (!file) return;
    if (file.size > MAX_IMPORT_BYTES) {
      showNotice("That file is too large to import (limit 5 MB).", null, true);
      return;
    }
    readFileText(file)
      .then(importCsvText, function () {
        showNotice("Could not read that file.", null, true);
      })
      .catch(function (err) {
        showNotice("Import failed: " + (err && err.message ? err.message : "unexpected error") + ".", null, true);
      });
  }

  // ---- Month picker -------------------------------------------------------

  // Browsers without <input type="month"> show a text box; only a complete
  // YYYY-MM value is accepted.
  function onMonthInput() {
    if (L.isValidMonth(monthInput.value)) {
      setMonth(monthInput.value);
    } else if (monthInput.value.length >= 7) {
      monthInput.setAttribute("aria-invalid", "true");
    }
  }

  function shiftSelectedMonth(delta) {
    var m = L.shiftMonth(selectedMonth, delta);
    if (m) setMonth(m);
  }

  // ---- Other tabs ---------------------------------------------------------

  function onStorage(e) {
    if (e.key === EXPENSES_KEY) {
      expenses = loadExpenses();
      render();
    } else if (e.key === BUDGETS_KEY) {
      budgets = loadBudgets();
      if (budgetDirty) {
        // Don't wipe what the user is typing here.
        budgetSavedEl.textContent = "Budgets were changed in another tab. Saving here will replace them.";
      } else {
        fillBudgetFields();
      }
      renderSummary();
    }
  }

  // ---- Init ---------------------------------------------------------------

  L.CATEGORIES.forEach(function (cat) {
    var opt = makeEl("option", null, cat);
    opt.value = cat;
    fields.category.appendChild(opt);
  });
  fields.date.value = L.toISODate(new Date());

  expenses = loadExpenses();
  budgets = loadBudgets();
  buildBudgetFields();
  fillBudgetFields();

  form.addEventListener("submit", onSubmit);
  Object.keys(fields).forEach(function (name) {
    // Clear a field's error as soon as the user edits it.
    fields[name].addEventListener("input", function () {
      setFieldError(fields[name], $(name + "-error"), "");
    });
  });

  budgetForm.addEventListener("submit", onBudgetSubmit);

  monthInput.addEventListener("input", onMonthInput);
  monthInput.addEventListener("change", onMonthInput);
  monthInput.addEventListener("blur", function () {
    // Cleared or half-typed: put the selected month back.
    if (!L.isValidMonth(monthInput.value)) renderSummary();
  });
  prevMonthBtn.addEventListener("click", function () { shiftSelectedMonth(-1); });
  nextMonthBtn.addEventListener("click", function () { shiftSelectedMonth(1); });

  barChartEl.addEventListener("mouseover", function (e) {
    var row = rowFromEvent(e);
    if (row && row !== activeRow) showTooltip(row);
  });
  barChartEl.addEventListener("mouseleave", hideTooltip);
  barChartEl.addEventListener("focusin", function (e) {
    var row = rowFromEvent(e);
    if (row) showTooltip(row);
  });
  barChartEl.addEventListener("focusout", hideTooltip);
  barChartEl.addEventListener("keydown", function (e) {
    if (e.key === "Escape") hideTooltip();
  });

  exportBtn.addEventListener("click", exportCsv);
  importInput.addEventListener("change", onImportFile);

  window.addEventListener("storage", onStorage);

  render();
})();

