const L = require('./logic.js');
const C = require('./csv.js');
const B = require('./budget.js');
const assert = require('assert');
const vm = require('vm'); const fs = require('fs');

function makeEnv(initialStore, opts = {}) {
  const els = {};
  let focused = null;
  const blobs = [];
  function el(tag, id) {
    const e = { tagName: tag, id, value: '', textContent: '', hidden: false, disabled: false, children: [], attrs: {}, listeners: {},
      className: '', title: '', tabIndex: -1, style: {}, parent: null, validity: { badInput: false }, files: null,
      offsetLeft: 100, offsetTop: 40, offsetWidth: 50, clientWidth: 600,
      get classList() { const self = this; const has = c => self.className.split(' ').includes(c); return {
        add(c) { if (!has(c)) self.className = (self.className + ' ' + c).trim(); },
        remove(c) { self.className = self.className.split(' ').filter(x => x !== c).join(' '); },
        toggle(c, on) { if (on) this.add(c); else this.remove(c); }, contains: has }; },
      appendChild(c) { if (c.isFrag) { c.children.forEach(k => this.appendChild(k)); return c; } c.parent = this; this.children.push(c); if (c.id) els[c.id] = c; return c; },
      replaceChildren(...k) { this.children = []; k.forEach(c => this.appendChild(c)); },
      remove() {}, click() {},
      setAttribute(k, v) { this.attrs[k] = String(v); }, removeAttribute(k) { delete this.attrs[k]; },
      addEventListener(t, f) { this.listeners[t] = f; }, focus() { focused = this; },
      querySelector(sel) { const cls = sel.slice(1); const walk = n => { for (const c of n.children) { if (c.className.split(' ').includes(cls)) return c; const r = walk(c); if (r) return r; } return null; }; return walk(this); },
      closest(sel) { const cls = sel.slice(1); let n = this; while (n) { if ((n.className || '').split(' ').includes(cls)) return n; n = n.parent; } return null; } };
    return e;
  }
  const getEl = id => els[id] || (els[id] = el('div', id));
  const store = Object.assign({}, initialStore);
  const windowListeners = {};
  const localStorage = {
    getItem: k => { if (opts.noStorage) throw new Error('blocked'); return k in store ? store[k] : null; },
    setItem: (k, v) => { if (opts.noStorage || (opts.failBackup && k.includes('.backup-')) || (opts.failAll)) throw new Error('quota'); store[k] = String(v); },
    get length() { return Object.keys(store).length; },
    key: i => Object.keys(store)[i]
  };
  const ctx = { console, Date, Math, JSON, Object, String, Number, Array, Promise, setTimeout: () => {},
    Blob: function (parts) { this.parts = parts; blobs.push(this); }, URL: { createObjectURL: () => 'blob:x', revokeObjectURL() {} },
    document: { getElementById: getEl, createElement: t => el(t), createDocumentFragment: () => { const f = el('#frag'); f.isFrag = true; f.appendChild = function (c) { this.children.push(c); return c; }; return f; }, body: el('body') },
    localStorage, window: { addEventListener(t, f) { windowListeners[t] = f; }, ExpenseLogic: L, ExpenseCSV: C, ExpenseBudget: B } };
  vm.createContext(ctx);
  vm.runInContext(fs.readFileSync('./app.js', 'utf8'), ctx);
  return { getEl, store, blobs, windowListeners, focused: () => focused };
}

const month = L.monthOf(L.toISODate(new Date()));
const good = L.createExpense({ amount: 10, category: 'Food', date: month + '-01' }, 'g', 1);
const future = { id: 'h', amount: 5, category: 'Health', date: month + '-02', note: '', createdAt: 2 };
const EK = 'expense-tracker.expenses', BK = 'expense-tracker.budgets';

// 1. Clean load: no notice, no backup
{
  const env = makeEnv({ [EK]: JSON.stringify([good]) });
  assert.strictEqual(env.getEl('notice').hidden, false === true);
  assert.ok(!Object.keys(env.store).some(k => k.includes('backup')));
  assert.strictEqual(env.getEl('expense-list').children.length, 1);
}

// 2. Lossy load (unknown category): backup made BEFORE any save, notice shown, then saving is allowed
{
  const raw = JSON.stringify([good, future]);
  const env = makeEnv({ [EK]: raw });
  const backups = Object.keys(env.store).filter(k => k.startsWith(EK + '.backup-'));
  assert.strictEqual(backups.length, 1);
  assert.strictEqual(env.store[backups[0]], raw, 'original kept byte-for-byte');
  assert.ok(env.getEl('notice-text').textContent.startsWith("1 saved entry in expenses couldn't be read"), env.getEl('notice-text').textContent);
  assert.ok(env.getEl('notice-text').textContent.includes(backups[0]));
  assert.ok(env.getEl('notice').className.includes('is-error'));
  // add an expense -> main key overwritten, backup intact
  env.getEl('amount').value = '3'; env.getEl('category').value = 'Fun'; env.getEl('date').value = month + '-03';
  env.getEl('expense-form').listeners.submit({ preventDefault() {} });
  assert.strictEqual(JSON.parse(env.store[EK]).length, 2);
  assert.strictEqual(env.store[backups[0]], raw);
  // storage event reload doesn't create a duplicate backup
  env.store[EK] = raw;
  env.windowListeners.storage({ key: EK });
  assert.strictEqual(Object.keys(env.store).filter(k => k.startsWith(EK + '.backup-')).length, 1);
}

// 3. Unreadable JSON: backed up
{
  const env = makeEnv({ [EK]: '{bad json' });
  const backups = Object.keys(env.store).filter(k => k.startsWith(EK + '.backup-'));
  assert.strictEqual(env.store[backups[0]], '{bad json');
  assert.ok(env.getEl('notice-text').textContent.includes('the data is damaged'));
}

// 4. Backup impossible: key is locked, original never overwritten
{
  const raw = JSON.stringify([good, future]);
  const env = makeEnv({ [EK]: raw }, { failBackup: true });
  assert.ok(env.getEl('notice-text').textContent.includes("won't be saved in this session"));
  env.getEl('amount').value = '3'; env.getEl('category').value = 'Fun'; env.getEl('date').value = month + '-03';
  env.getEl('expense-form').listeners.submit({ preventDefault() {} });
  assert.strictEqual(env.store[EK], raw, 'original untouched');
  assert.strictEqual(env.getEl('expense-list').children.length, 2, 'still usable in memory');
  assert.ok(env.getEl('notice-text').textContent.includes('could not be saved'));
}

// 5. Budgets get the same protection
{
  const raw = '{"Food":100,"Health":5}';
  const env = makeEnv({ [BK]: raw });
  const backups = Object.keys(env.store).filter(k => k.startsWith(BK + '.backup-'));
  assert.strictEqual(env.store[backups[0]], raw);
  assert.strictEqual(env.getEl('budget-food').value, '100.00');
}

// 6. Storage blocked entirely: works in memory with a notice
{
  const env = makeEnv({}, { noStorage: true });
  assert.ok(env.getEl('notice-text').textContent.includes("isn't available"));
  env.getEl('amount').value = '3'; env.getEl('category').value = 'Fun'; env.getEl('date').value = month + '-03';
  env.getEl('expense-form').listeners.submit({ preventDefault() {} });
  assert.strictEqual(env.getEl('total').textContent, '3.00');
}

// 7. Form: strict amounts, badInput, aria wiring
{
  const env = makeEnv({});
  const submit = () => env.getEl('expense-form').listeners.submit({ preventDefault() {} });
  env.getEl('category').value = 'Food'; env.getEl('date').value = month + '-05';
  env.getEl('amount').value = '1.005'; submit();
  assert.ok(env.getEl('amount-error').textContent.includes('2 decimal places'));
  assert.strictEqual(env.getEl('amount').attrs['aria-invalid'], 'true');
  env.getEl('amount').value = ''; env.getEl('amount').validity = { badInput: true }; submit();
  assert.strictEqual(env.getEl('amount-error').textContent, 'Amount is not a number.');
  env.getEl('amount').validity = { badInput: false };
  env.getEl('amount').value = '1e21'; submit();
  assert.ok(env.getEl('amount-error').textContent.includes('not a number'));
  env.getEl('amount').value = '12.50'; submit();
  assert.strictEqual(env.getEl('total').textContent, '12.50');
  assert.strictEqual(env.getEl('amount').value, '');
}

// 8. Budgets: strict input, dirty form survives another tab's save, zero budgets footer
{
  const env = makeEnv({ [EK]: JSON.stringify([good]) });
  env.getEl('budget-food').value = '0.004';
  env.getEl('budget-form').listeners.submit({ preventDefault() {} });
  assert.ok(env.getEl('budget-food-error').textContent.includes('2 decimal places'));
  env.getEl('budget-food').value = '0'; env.getEl('budget-food').listeners.input();
  env.getEl('budget-form').listeners.submit({ preventDefault() {} });
  assert.strictEqual(env.getEl('budget-saved').textContent, 'Budgets saved.');
  const foot = env.getEl('summary-table').children[5].children.map(c => c.textContent);
  assert.deepStrictEqual(foot.slice(4), ['0.00', '>100% of budgeted']);
  const foodRow = env.getEl('bar-chart').children[0];
  assert.ok(foodRow.className.includes('is-over'));
  // dirty edit, then another tab saves budgets
  env.getEl('budget-fun').value = '25'; env.getEl('budget-fun').listeners.input();
  env.store[BK] = '{"Bills":50}';
  env.windowListeners.storage({ key: BK });
  assert.strictEqual(env.getEl('budget-fun').value, '25', 'typed value kept');
  assert.ok(env.getEl('budget-saved').textContent.includes('another tab'));
  // when clean, other-tab changes are filled in
  env.getEl('budget-form').listeners.submit({ preventDefault() {} });
  env.store[BK] = '{"Bills":50}';
  env.windowListeners.storage({ key: BK });
  assert.strictEqual(env.getEl('budget-bills').value, '50.00');
  assert.strictEqual(env.getEl('budget-fun').value, '');
}

// 9. Month buttons disabled at the limits
{
  const env = makeEnv({});
  assert.strictEqual(env.getEl('prev-month').disabled, false);
  env.getEl('month').value = '9999-12'; env.getEl('month').listeners.change();
  assert.strictEqual(env.getEl('next-month').disabled, true);
  env.getEl('next-month').listeners.click();
  assert.strictEqual(env.getEl('month').value, '9999-12');
  env.getEl('month').value = '0000-01'; env.getEl('month').listeners.change();
  assert.strictEqual(env.getEl('prev-month').disabled, true);
}

// 10. Import: comma notes rejoined, export round trip, huge import doesn't crash
(async () => {
  const tick = () => new Promise(r => setImmediate(r));
  const env = makeEnv({});
  const importText = async (text) => { env.getEl('import-file').files = [{ size: text.length, text: async () => text }]; env.getEl('import-file').listeners.change(); await tick(); await tick(); await tick(); };
  await importText('date,category,amount,note\n' + month + '-01,Food,5,Lunch, with Sam\n' + month + '-02,Fun,1e3,x\n');
  assert.ok(env.getEl('notice-text').textContent.startsWith('Imported 1 expense.'), env.getEl('notice-text').textContent);
  assert.deepStrictEqual(env.getEl('notice-errors').children.map(c => c.textContent), ['Line 3: Amount "1e3" is not a number.']);
