const month = L.monthOf(L.toISODate(new Date()));
const good = L.createExpense({ amount: 10, category: 'Food', date: month + '-01' }, 'g', 1);
const future = { id: 'h', amount: 5, category: 'Health', date: month + '-02', note: '', createdAt: 2 };
const EK = 'expense-tracker.expenses', BK = 'expense-tracker.budgets';

// 1. Clean load: no notice, no backup
{
  const env = makeEnv({ [EK]: JSON.stringify([good]) });
  assert.strictEqual(env.getEl('notice').hidden, false === true);
  assert.ok(!Object.keys(env.store).some(k => k.includes('backup')));
  assert.strictEqual(env.getEl('expense-list').children.length, 1);
}

// 2. Lossy load (unknown category): backup made BEFORE any save, notice shown, then saving is allowed
{
  const raw = JSON.stringify([good, future]);
  const env = makeEnv({ [EK]: raw });
  const backups = Object.keys(env.store).filter(k => k.startsWith(EK + '.backup-'));
  assert.strictEqual(backups.length, 1);
  assert.strictEqual(env.store[backups[0]], raw, 'original kept byte-for-byte');
  assert.ok(env.getEl('notice-text').textContent.startsWith("1 saved entry in expenses couldn't be read"), env.getEl('notice-text').textContent);
  assert.ok(env.getEl('notice-text').textContent.includes(backups[0]));
  assert.ok(env.getEl('notice').className.includes('is-error'));
  // add an expense -> main key overwritten, backup intact
  env.getEl('amount').value = '3'; env.getEl('category').value = 'Fun'; env.getEl('date').value = month + '-03';
  env.getEl('expense-form').listeners.submit({ preventDefault() {} });
  assert.strictEqual(JSON.parse(env.store[EK]).length, 2);
  assert.strictEqual(env.store[backups[0]], raw);
  // storage event reload doesn't create a duplicate backup
  env.store[EK] = raw;
  env.windowListeners.storage({ key: EK });
  assert.strictEqual(Object.keys(env.store).filter(k => k.startsWith(EK + '.backup-')).length, 1);
}

// 3. Unreadable JSON: backed up
{
  const env = makeEnv({ [EK]: '{bad json' });
  const backups = Object.keys(env.store).filter(k => k.startsWith(EK + '.backup-'));
  assert.strictEqual(env.store[backups[0]], '{bad json');
  assert.ok(env.getEl('notice-text').textContent.includes('the data is damaged'));
}

