{
  const raw = JSON.stringify([good, future]);
  const env = makeEnv({ [EK]: raw }, { failBackup: true });
  assert.ok(env.getEl('notice-text').textContent.includes("won't be saved in this session"));
  env.getEl('amount').value = '3'; env.getEl('category').value = 'Fun'; env.getEl('date').value = month + '-03';
  env.getEl('expense-form').listeners.submit({ preventDefault() {} });
  assert.strictEqual(env.store[EK], raw, 'original untouched');
  assert.strictEqual(env.getEl('expense-list').children.length, 2, 'still usable in memory');
  assert.ok(env.getEl('notice-text').textContent.includes('could not be saved'));
}

// 5. Budgets get the same protection
{
  const raw = '{"Food":100,"Health":5}';
  const env = makeEnv({ [BK]: raw });
  const backups = Object.keys(env.store).filter(k => k.startsWith(BK + '.backup-'));
  assert.strictEqual(env.store[backups[0]], raw);
  assert.strictEqual(env.getEl('budget-food').value, '100.00');
}

// 6. Storage blocked entirely: works in memory with a notice
{
  const env = makeEnv({}, { noStorage: true });
  assert.ok(env.getEl('notice-text').textContent.includes("isn't available"));
  env.getEl('amount').value = '3'; env.getEl('category').value = 'Fun'; env.getEl('date').value = month + '-03';
  env.getEl('expense-form').listeners.submit({ preventDefault() {} });
  assert.strictEqual(env.getEl('total').textContent, '3.00');
}

// 7. Form: strict amounts, badInput, aria wiring
{
  const env = makeEnv({});
  const submit = () => env.getEl('expense-form').listeners.submit({ preventDefault() {} });
  env.getEl('category').value = 'Food'; env.getEl('date').value = month + '-05';
  env.getEl('amount').value = '1.005'; submit();
  assert.ok(env.getEl('amount-error').textContent.includes('2 decimal places'));
  assert.strictEqual(env.getEl('amount').attrs['aria-invalid'], 'true');
  env.getEl('amount').value = ''; env.getEl('amount').validity = { badInput: true }; submit();
  assert.strictEqual(env.getEl('amount-error').textContent, 'Amount is not a number.');
  env.getEl('amount').validity = { badInput: false };
  env.getEl('amount').value = '1e21'; submit();
  assert.ok(env.getEl('amount-error').textContent.includes('not a number'));
  env.getEl('amount').value = '12.50'; submit();
  assert.strictEqual(env.getEl('total').textContent, '12.50');
  assert.strictEqual(env.getEl('amount').value, '');
}

// 8. Budgets: strict input, dirty form survives another tab's save, zero budgets footer
{
  const env = makeEnv({ [EK]: JSON.stringify([good]) });
  env.getEl('budget-food').value = '0.004';
  env.getEl('budget-form').listeners.submit({ preventDefault() {} });
  assert.ok(env.getEl('budget-food-error').textContent.includes('2 decimal places'));
  env.getEl('budget-food').value = '0'; env.getEl('budget-food').listeners.input();
  env.getEl('budget-form').listeners.submit({ preventDefault() {} });
  assert.strictEqual(env.getEl('budget-saved').textContent, 'Budgets saved.');
  const foot = env.getEl('summary-table').children[5].children.map(c => c.textContent);
  assert.deepStrictEqual(foot.slice(4), ['0.00', '>100% of budgeted']);
  const foodRow = env.getEl('bar-chart').children[0];
