  assert.strictEqual(env.getEl('notice-text').textContent, 'Nothing new to import. 1 row already in your list was skipped.');

  const big = 'date,category,amount\n' + Array.from({ length: 150000 }, () => '2026-01-01,Food,1').join('\n');
  await importText(big);
  assert.ok(env.getEl('notice-text').textContent.startsWith('Imported 150,000'.replace(',', '')) || env.getEl('notice-text').textContent.startsWith('Imported 150000'), env.getEl('notice-text').textContent);
  assert.strictEqual(env.getEl('expense-list').children.length, 150001);
  console.log('step 5 app smoke test passed');
})().catch(e => { console.error(e); process.exit(1); });
